public void run() {
    // CLR90 p489
    // 1. DFS to compute finishing times on Map
    melton.hayden.jepends.algorithm.ttcormenetal.CLR90DFS<K> dfs = new melton.hayden.jepends.algorithm.ttcormenetal.CLR90DFS<K>(this.map);
    dfs.run();
    // 2. consider vertices in descending order of finishing time
    final java.util.Map<K, java.lang.Integer> finishedMap = dfs.getFinishedMap();
    java.util.LinkedList<K> ll = new java.util.LinkedList<K>(finishedMap.keySet());
    java.util.Collections.<K>sort(ll, new java.util.Comparator<K>() {
        1() {
            super();
        }

        public int compare(K left, K right) {
            return finishedMap.get(left) - finishedMap.get(right);
        }
    });
    java.util.Collections.reverse(ll);
    // 3. dfs on MapT
    melton.hayden.jepends.algorithm.ttcormenetal.CLR90DFS<K> dfsT = new melton.hayden.jepends.algorithm.ttcormenetal.CLR90DFS<K>(this.mapT);
    dfsT.run(ll);
    // 4. output trees as SCCs
    this.sccs = new java.util.LinkedList<java.util.Set<K>>(dfsT.getTrees());
    java.util.Collections.<java.util.Set<K>>sort(this.sccs, new java.util.Comparator<java.util.Set<K>>() {
        2() {
            super();
        }

        public int compare(java.util.Set<K> left, java.util.Set<K> right) {
            return left.size() - right.size();
        }
    });
    /* for (Set<K> set : sccs) {
    System.out.println(set);
    }
     */
}

