public static java.util.Map<java.lang.String, java.util.Set<java.lang.String>> merge(java.util.Map<java.lang.String, java.util.Set<java.lang.String>> table) {
    java.util.Map<java.lang.String, java.util.Set<java.lang.String>> mtable = new java.util.HashMap<java.lang.String, java.util.Set<java.lang.String>>();
    for (java.lang.String key : table.keySet()) {
        java.util.Set<java.lang.String> fanout = table.get(key);
        for (java.lang.String key2 : table.keySet()) {
            if (key.equals(key2)) {
                fanout.addAll(table.get(key2));
            }
        }
        // remove self referencing
        fanout.remove(key);
        // add to map
        mtable.put(key, fanout);
    }
    return mtable;
}

public int[] adjPathFromAToB(int a, int b, int dist) {
    int[] adjPathsAToB = new int[dist];
    // The path will always end at b.
    // pathsAToB.add(b);
    int index = 0;
    adjPathsAToB[index] = b;
    // Loop through each previous vertex until you get back to start.
    try {
        while (this.path[a][b] != a) {
            adjPathsAToB[++index] = this.path[a][b];
            b = this.path[a][b];
        } 
        // Add start to the beginning of path
        adjPathsAToB[++index] = a;
    } catch (java.lang.Exception e) {
        adjPathsAToB = new int[dist];
    }
    return adjPathsAToB;
}

