private void fitnessHistogram(java.util.Map<java.lang.String, java.util.Set<java.lang.String>> map, boolean pre) {
    tosin.oyetoyan.refsimulator.support.GraphData g = new tosin.oyetoyan.refsimulator.support.GraphData(map, tosin.oyetoyan.refsimulator.support.GraphData.CRSS);
    g.run();
