        this.fitness.setPreRefactoring_Histogram(hist.getHistogram());
    } else {
        this.fitness.setPostRefactoring_Histogram(hist.getHistogram());
    }
}

public void simulateSystem(int numRefactor) {
    long startTime = java.lang.System.currentTimeMillis();
    // re-initialise the maps
    this.initializeMaps();
    this.finalCand = new java.util.ArrayList<java.lang.String>();
    this.refactoredEdges = new java.util.ArrayList<tosin.oyetoyan.refsimulator.support.RefactoredEdges>();
    this.fitness = new tosin.oyetoyan.refsimulator.support.fitness.FitnessValuesSystem();
    // fitness - pre refactoring
    this.fitnessSCC(this.map, true);
    this.fitnessHistogram(this.map, true);
    java.util.List<java.lang.Double> postFitMean = new java.util.ArrayList<java.lang.Double>();
    java.util.List<java.lang.Double> postFitStdDev = new java.util.ArrayList<java.lang.Double>();
    java.lang.Double[] fit = new java.lang.Double[2];
    this.fitnessFunction(this.map, fit);
    this.fitness.setPreRefactoring_Mean(fit[0]);
    this.fitness.setPreRefactoring_StdDev(fit[1]);
    this.fitness.setPreRefactoringNumberOfComponents(this.map.keySet().size());
    this.fitness.setPreRefactoringNumberOfEdges(this.calcOfEdges());
    if (numRefactor == 0) {
        this.dsTable2 = new tosin.oyetoyan.refsimulator.support.DecisionSupportTable2();
        return;
    }
    // check if main class exist
    if (!this.map.containsKey(this.mainClass)) {
        this.map.put(this.mainClass, new java.util.HashSet<java.lang.String>());// create it in map, it means we are using a dummy/new entry point

        this.refactoredEdges.add(new tosin.oyetoyan.refsimulator.support.RefactoredEdges(this.mainClass, "", tosin.oyetoyan.refsimulator.support.ModelSimulator.CREATE, tosin.oyetoyan.refsimulator.support.ModelSimulator.NEWCLASS));// add to refactored edge list

    }
    int index = 0;
    tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1 fed = new tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1(this.map, this.ptMap, this.mtMap, this.tMap, this.sortPriority);
    tosin.oyetoyan.refsimulator.support.DecisionSupportTable2 dst2 = new tosin.oyetoyan.refsimulator.support.DecisionSupportTable2();
    if (this.isPreRefactor()) {
        numRefactor = this.selectedCand.size();
    }
    for (int i = 0; i < numRefactor; i++) {
        java.lang.String target;
        boolean isSingleton = false;
        if (!this.isPreRefactor()) {
            fed.processCandidates(this.topKcrss, this.topKscc, this.topKfanin, this.reductionRate);
            java.util.List<tosin.oyetoyan.refsimulator.support.DiffExtractInterface> candidates = fed.getCandidates();
            // comment block to compare with manual selection
            if (i > 0) {
                // recompute the candidate list for new opportunities
                fed.updateTable(this.map, this.ptMap, this.mtMap, this.tMap);// call update table

                fed.processCandidates(this.topKcrss, this.topKscc, this.topKfanin, this.reductionRate);
                candidates = fed.getCandidates();
            }
            // remove serviceLocator,  and already-refactored candidates from the list of candidates
            this.removeCandidate(candidates, this.serviceLocator);
            this.removeCandidate(candidates, this.mainClass);
            for (java.lang.String toRemove : this.finalCand) {
                this.removeCandidate(candidates, toRemove);
            }
            if (candidates.size() == 0) {
                break;
            }
            tosin.oyetoyan.refsimulator.support.DiffExtractInterface ei = candidates.get(index);
            isSingleton = ei.isZtatic();
            target = ei.getComp();
        } else {
            target = this.selectedCand.get(i);
        }
        java.lang.String interfaze = target + "_Interface";
        // refactor
        this.useOnlyMFES = false;
        this.registry("", target, interfaze, dst2, isSingleton);
        // update dstable2
        this.setDSTable2Maps(dst2);
        dst2.updateTable(this.map);
        // final candidate
        this.finalCand.add(target);
        // now add fitness of each refactoring iteration
        fit = new java.lang.Double[2];
        this.fitnessFunction(this.map, fit);// fitness function for map after refactoring

        postFitMean.add(fit[0]);
        postFitStdDev.add(fit[1]);
    }
    long endTime = java.lang.System.currentTimeMillis() - startTime;
    this.fitness.setRuntime(endTime);
    // add fitness of all the iterations after refactoring
    this.fitness.setPostRefactoring_Mean(postFitMean);
    this.fitness.setPostRefactoring_StdDev(postFitStdDev);
    this.fitness.setPostRefactoringNumberOfComponents(this.map.keySet().size());
    this.fitness.setPostRefactoringNumberOfEdges(this.calcOfEdges());
    this.fitnessSCC(this.map, false);
    this.fitnessHistogram(this.map, false);
    // update map
    this.updateMapsAfterRefactoring();
    this.setDsTable2(dst2);
}

