private void refactorExtractInterface(java.lang.String fanin, java.lang.String target, java.lang.String interfaze, tosin.oyetoyan.refsimulator.support.Table2Schema s) {
    this.replaceTargetWithInterface(fanin, target, interfaze);
    // update all maps for new interface
    this.updateInterface(interfaze);
    // ****find the original usage types btw source and target and transfer them to itarget****
    tosin.oyetoyan.refsimulator.support.ClassUsesTypes cut = s.getUsageTypes();
