    this.refactoredEdges.add(new tosin.oyetoyan.refsimulator.support.RefactoredEdges(fanin, interfaze, tosin.oyetoyan.refsimulator.support.ModelSimulator.USES, this.decision(s.getDecision_Set())));// 

