public robert.sheridan.algorithm.Graph getGraphWithoutCycles(int[] cycleEliminationPriority) {
    int priorityIndex[] = new int[this.nodecount];
    int x;
    for (x = 0; x < cycleEliminationPriority.length; x++) {
        priorityIndex[cycleEliminationPriority[x]] = x;
    }
    java.util.LinkedList newEdges = new java.util.LinkedList();
    for (x = 0; x < this.edge.length; x++) {
        int edgeFrom = this.edge[x].getFrom();
        int edgeTo = this.edge[x].getTo();
        if (edgeFrom == edgeTo) {
            continue;
        }/* drop onecycles */

        if (priorityIndex[edgeFrom] > priorityIndex[edgeTo]) {
            int temp = edgeFrom;
            edgeFrom = edgeTo;
            edgeTo = temp;
            newEdges.add(new robert.sheridan.algorithm.Edge(edgeFrom, edgeTo));
        } else {
            newEdges.add(this.edge[x]);
        }
    }
    robert.sheridan.algorithm.Edge newEdge[] = new robert.sheridan.algorithm.Edge[newEdges.size()];
    newEdges.<java.lang.Object>toArray(newEdge);
    robert.sheridan.algorithm.Graph dag = new robert.sheridan.algorithm.Graph(this.nodecount, newEdge);
    dag.acyclic = true;
    return dag;
}

private void fitnessFunctionMeanAndStdDev() {
    /* We use the crss mean value or the standard deviation of crss from the mean
    after a set of refactorings on candidates have been done
     */
    // compute the crss
    java.util.Map<java.lang.String, java.util.Set<java.lang.String>> reachabilityMap = null;
    try {
        reachabilityMap = new melton.hayden.jepends.algorithm.ReachabilityMapGenerator<java.lang.String>(this.map).getMap();
    } catch (java.lang.Exception e) {
        reachabilityMap = new melton.hayden.jepends.algorithm.ReachabilityMapGenerator<java.lang.String>(this.map).getMap();
    }
    org.apache.commons.math3.stat.descriptive.SummaryStatistics sm = new org.apache.commons.math3.stat.descriptive.SummaryStatistics();
    for (java.lang.String k : reachabilityMap.keySet()) {
        double value = reachabilityMap.get(k).size();
        sm.addValue(value);
    }
    this.fitness.setPreRefactoring_Mean(sm.getMean());
    this.fitness.setPreRefactoring_StdDev(sm.getStandardDeviation());
}

public CycleRemoval(java.util.Set<java.lang.String> scc, java.util.Map<java.lang.String, java.util.Set<java.lang.String>> map, java.util.Map<java.lang.String, java.util.Set<java.lang.String>> supersMap, tosin.oyetoyan.refsimulator.graph.CycleMatrix cm) {
    super();
    this.cycleGraph = cm;// call CycleMatrix

    this.graph = this.cycleGraph.getGraph();
    this.collectEdgeFromGraph();
    this.exclude = tosin.oyetoyan.refsimulator.utility.CreateMap.createExcludeEdges(supersMap, this.cycleGraph.getScc_lookUp());
    this.excludeNodes = tosin.oyetoyan.refsimulator.utility.CreateMap.createExcludeNodes(supersMap, this.cycleGraph.getScc_lookUp());
    this.callCycleRemovalAlgorithm(this.exclude);
}

