    refReport.get("class").add("#fanin");
    refReport.get("class").add("#fanout");
    refReport.get("class").add("#EndOfRef_");
    // }
    for (java.lang.String k : this.simulate.getReportRefactors().keySet()) {
        java.util.List<tosin.oyetoyan.refsimulator.support.Refactored> sr = this.simulate.getReportRefactors().get(k);
        java.util.List<java.lang.String> data = new java.util.LinkedList<java.lang.String>();
        for (int i = 0; i < sr.size(); i++) {
            tosin.oyetoyan.refsimulator.support.Refactored r = sr.get(i);
            if (r.getNumRefactoring() == this.simulate.getFinalRefactorNumber()) {
                data.add(r.getNumRefactoring() + "");
                data.add(r.getCrss() + "");
                data.add(r.getScc() + "");
                data.add(r.getIndegree() + "");
                data.add(r.getOutdegree() + "");
                data.add("");
                // break;
            }
        }
        refReport.put(k, data);
    }
    melton.hayden.jepends.analysis.MapFileWriter writer = new melton.hayden.jepends.analysis.MapFileWriter(refReport, new java.io.File(outFile));
    writer.write();
}

