public int[] getVertexLayers() {
    if (!this.reduced) {
        throw new java.lang.RuntimeException("attempt to compute vertex layers in a non-reduced graph");
    }
    final int LAYER_WIDTH = java.lang.Math.max(((int) (java.lang.Math.pow(this.nodecount, 2 / java.lang.Math.PI))), 10);
    int vertexLabel[] = new int[this.nodecount];
    int x;
    for (x = 0; x < this.nodecount; x++) {
        vertexLabel[x] = 0;/* 0 is the "unlabelled" label */

    }
    int parentLabels[][] = new int[this.nodecount][];
    java.util.LinkedHashSet eligible = new java.util.LinkedHashSet((this.nodecount * 3) / 2);
    boolean onEligible[] = new boolean[this.nodecount];
    /* add all sources and isolated nodes to eligible list */
    for (x = 0; x < this.nodecount; x++) {
        if (this.edgesTo[x].size() == 0) {
            eligible.add(new java.lang.Integer(x));
            onEligible[x] = true;
        } else {
            onEligible[x] = false;
        }
    }
    int nextLabel = 1;
    while (eligible.size() > 0) {
        /* find minimal node */
        java.util.Iterator iter = eligible.iterator();
        java.lang.Integer minElement = ((java.lang.Integer) (iter.next()));
        int minId = minElement.intValue();
        while (iter.hasNext()) {
            int nextId = ((java.lang.Integer) (iter.next())).intValue();
            if (robert.sheridan.algorithm.Graph.orderedSetComparison(parentLabels[nextId], parentLabels[minId])) {
                minId = nextId;
            }
        } 
        vertexLabel[minId] = nextLabel++;
        eligible.remove(minElement);
        onEligible[minId] = false;
        /* check children for eligibility */
        iter = this.edgesFrom[minId].iterator();
        NEXTCHILD : while (iter.hasNext()) {
            int childId = ((java.lang.Integer) (iter.next())).intValue();
            if (onEligible[childId]) {
                continue NEXTCHILD;
            }/* already eligible */

            java.util.Iterator cpIter = this.edgesTo[childId].iterator();
            int childParentList[] = new int[this.edgesTo[childId].size()];/* warning: multigraphs will mess this up */

            int childParentListIndex = 0;
            while (cpIter.hasNext()) {
                int childParentId = ((java.lang.Integer) (cpIter.next())).intValue();
                if (vertexLabel[childParentId] == 0) {
                    /* unlabelled parent -- ineligible */
                    continue NEXTCHILD;
                }
                childParentList[childParentListIndex++] = childParentId;
            } 
            /* all child's parents are labelled .. make eligible */
            /* tidy up childParent array */
            java.util.Arrays.sort(childParentList);
            parentLabels[childId] = new int[childParentList.length];
            int parentLabelsIndex = 0;
            for (x = childParentList.length - 1; x >= 0; x--) {
                parentLabels[childId][parentLabelsIndex++] = vertexLabel[childParentList[x]];
            }
            /* add to eligible */
            eligible.add(new java.lang.Integer(childId));
            onEligible[childId] = true;
        } 
    } 
    /* all nodes now labelled - assign to layers */
    int vertexLayer[] = new int[this.nodecount];
    for (x = 0; x < this.nodecount; x++) {
        vertexLayer[x] = 0;/* 0 means unassigned */

    }
    eligible.clear();
    java.util.LinkedHashSet nominated = new java.util.LinkedHashSet();
    /* add all sinks and isolated nodes to eligible */
    for (x = 0; x < this.nodecount; x++) {
        if (this.edgesFrom[x].size() == 0) {
            eligible.add(new java.lang.Integer(x));
        }
    }
    int currentLayer = 1;
    while (eligible.size() > 0) {
        /* sort eligible and fill layer */
        int currentLayerSize = 0;
        java.lang.Integer eligibleSort[] = new java.lang.Integer[eligible.size()];
        eligible.<java.lang.Object>toArray(eligibleSort);
        java.util.Arrays.sort(eligibleSort);
        int eligibleIndex;
        for (eligibleIndex = eligibleSort.length - 1; eligibleIndex >= 0; eligibleIndex--) {
            if (currentLayerSize == LAYER_WIDTH) {
                break;
            }
            /* add next node to layer */
            int nodeId = eligibleSort[eligibleIndex].intValue();
            vertexLayer[nodeId] = currentLayer;
            currentLayerSize++;
            /* nominate parents */
            java.util.Iterator iter = this.edgesTo[nodeId].iterator();
            NEXTPARENT : while (iter.hasNext()) {
                java.lang.Integer parentObj = ((java.lang.Integer) (iter.next()));
                int parentId = parentObj.intValue();
                if (vertexLayer[parentId] > 0) {
                    /* parent already done -- do not nominate */
                    continue NEXTPARENT;
                }
                java.util.Iterator pcIter = this.edgesFrom[parentId].iterator();
                while (pcIter.hasNext()) {
                    int parentChildId = ((java.lang.Integer) (pcIter.next())).intValue();
                    if (vertexLayer[parentChildId] == 0) {
                        /* unassigned child -- parent not nominated */
                        continue NEXTPARENT;
                    }
                } 
                nominated.add(parentObj);
            } 
            /* remove from eligible */
            eligible.remove(new java.lang.Integer(nodeId));
            nominated.remove(new java.lang.Integer(nodeId));
        }
        currentLayer++;
        /* make nominees eligible */
        eligible.addAll(nominated);
    } 
    return vertexLayer;
}

public Graph(int a_nodecount, robert.sheridan.algorithm.Edge[] a_edge) {
    super();
    // System.out.println("Exclude-size: "+this.exclude.size());
    this.nodecount = a_nodecount;
    this.edge = new robert.sheridan.algorithm.Edge[a_edge.length];
    this.edgesFrom = new java.util.LinkedList[this.nodecount];
    this.edgesTo = new java.util.LinkedList[this.nodecount];
    int x;
    for (x = 0; x < this.nodecount; x++) {
        this.edgesFrom[x] = new java.util.LinkedList();
        this.edgesTo[x] = new java.util.LinkedList();
    }
    for (x = 0; x < a_edge.length; x++) {
        int edgeFrom = a_edge[x].getFrom();
        int edgeTo = a_edge[x].getTo();
        if ((((edgeFrom < 0) || (edgeTo >= this.nodecount)) || (edgeTo < 0)) || (edgeTo >= this.nodecount)) {
            throw new java.lang.IllegalArgumentException((((((("Edge refered to node outside of valid range: " + "From=") + edgeFrom) + " To=") + edgeTo) + " with nodecount=") + this.nodecount) + "\n");
        }
        this.edge[x] = new robert.sheridan.algorithm.Edge(edgeFrom, edgeTo);
        this.edgesFrom[edgeFrom].add(new java.lang.Integer(edgeTo));
        this.edgesTo[edgeTo].add(new java.lang.Integer(edgeFrom));
    }
    this.acyclic = false;
    this.reduced = false;
