public GraphDistance(int[][] g, java.lang.String type) {
    super();
    this.graph = g;
    this.path = new int[g.length][g.length];
    // Initialize with the previous vertex for each edge. -1 indicates
    // no such vertex.
    for (int i = 0; i < g.length; i++) {
        for (int j = 0; j < g.length; j++) {
            if ((g[i][j] == 0) && (i != j)) {
                this.path[i][j] = -1;
                g[i][j] = java.lang.Integer.MAX_VALUE;// reconstruct g such that where there is no path i -> j (for i!=j), assign high value

            } else {
                this.path[i][j] = i;
            }
        }
    }
    // This means that we don't have to go anywhere to go from i to i.
    for (int i = 0; i < g.length; i++) {
        this.path[i][i] = i;
    }
    if (type.equals(tosin.oyetoyan.refsimulator.graph.GraphDistance.LONGEST)) {
        g = this.negate(g);
    }
    this.pathdistance = this.distance(g, this.path, type);
}

