    this.scc = scc;
    this.sccData(true);
    // create a square matrix representation of scc
    tosin.oyetoyan.refsimulator.graph.CycleMatrix cm = new tosin.oyetoyan.refsimulator.graph.CycleMatrix(scc, this.map);
    if (excludeParents) {
        java.util.Random r = new java.util.Random();
        int seed = r.nextInt();
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> parents = new java.util.HashMap<java.lang.String, java.util.Set<java.lang.String>>(this.supersMap);
        tosin.oyetoyan.refsimulator.utility.MapUtil.setOfMap1PlusSetOfMap2(parents, this.interfaceMap);
        melton.hayden.jepends.analysis.FeedbackSetHeuristic feedback = new melton.hayden.jepends.analysis.FeedbackSetHeuristic(cm.getCyclicMap(), parents);
        feedback.run(new java.util.Random(seed), true);
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> toRemove = feedback.getEdgesToRemove();
        // mFES edges
        this.mFESdata = new java.util.ArrayList<tosin.oyetoyan.refsimulator.support.DecisionSupportCycles.Data>();
        for (java.lang.String from : toRemove.keySet()) {
            java.util.Set<java.lang.String> tos = toRemove.get(from);
            for (java.lang.String to : tos) {
                this.helperRun(from, to);
            }
        }
    } else {
        tosin.oyetoyan.refsimulator.graph.CycleRemoval rc = new tosin.oyetoyan.refsimulator.graph.CycleRemoval(scc, this.map, cm);
        java.lang.System.out.println("Edges: " + cm.getNumEdges());
        // mFES edges
        this.mFESdata = new java.util.ArrayList<tosin.oyetoyan.refsimulator.support.DecisionSupportCycles.Data>();
        // System.out.println("mFES edges");
        for (robert.sheridan.algorithm.Edge e : rc.getMinFES()) {
            java.lang.String from = rc.getCycleGraph().getScc_lookUp().get(e.getFrom());
            java.lang.String to = rc.getCycleGraph().getScc_lookUp().get(e.getTo());
            this.helperRun(from, to);
        }
    }
    // sort on reducedBy or Fanin
    this.sortCollection(sortPriority);
}

