public static void computePrePostCRSS(java.util.Map<java.lang.String, java.util.Set<java.lang.String>> map, java.util.Map<java.lang.String, tosin.oyetoyan.refsimulator.support.SCCCRSSData> candidatesCRSS, java.util.Set<java.lang.String> sources_, boolean pre) {
    // compute the crss,scc and dependOnSCC
    melton.hayden.jepends.analysis.Analyser analyse = new melton.hayden.jepends.analysis.Analyser();
    analyse.analyse(map);
    java.util.Map<java.lang.String, java.util.Set<java.lang.String>> reachabilityMap = analyse.getReachabilityMap();
    java.util.Map<java.lang.String, java.util.Set<java.lang.String>> dependOnSCC = analyse.getDependOnSCC();
    for (java.lang.String k : sources_) {
        double crssvalue = reachabilityMap.get(k).size();
        int dsccvalue = dependOnSCC.get(k).size();
        // set the CRSS values
        if (pre) {
            tosin.oyetoyan.refsimulator.support.SCCCRSSData crss = new tosin.oyetoyan.refsimulator.support.SCCCRSSData();
            crss.setPreCRSS(crssvalue);
            crss.setPreDependOnSCC(dsccvalue);
            candidatesCRSS.put(k, crss);
        } else {
            candidatesCRSS.get(k).setPostCRSS(crssvalue);
            candidatesCRSS.get(k).setPostDependOnSCC(dsccvalue);
        }
    }
