    if (split[0].trim().equals("")) {
        java.lang.System.out.println("empty string!");
        return;
    }
    java.lang.String key = split[0];
    java.util.Set<java.lang.String> set = new java.util.HashSet<java.lang.String>();
    java.lang.Object old = map.put(key, set);
    if (old != null) {
        throw new java.lang.RuntimeException("replaced a value in Map!");
    }
    for (int i = 1; i < split.length; i++) {
