private void removeCandidate(java.util.List<tosin.oyetoyan.refsimulator.support.DiffExtractInterface> candidates, java.lang.String candidate) {
    int index = -1;
    for (int i = 0; i < candidates.size(); i++) {
        tosin.oyetoyan.refsimulator.support.DiffExtractInterface ei = candidates.get(i);
        if (ei.getComp().equals(candidate)) {
            index = i;
            break;
        }
    }
    // now remove it
    try {
        candidates.remove(index);
    } catch (java.lang.Exception e) {
        // System.out.println(candidate);//do nothing...
    }
}

