private void minFES(robert.sheridan.algorithm.Graph cyclic, robert.sheridan.algorithm.Graph acyclic) {
    this.minFES_new = new java.util.ArrayList<robert.sheridan.algorithm.Edge>();
    for (int x = 0; x < this.a_edge.length; x++) {
        int edgeFrom_cyclic = cyclic.getEdge()[x].getFrom();
        int edgeTo_cyclic = cyclic.getEdge()[x].getTo();
        // 
        int edgeFrom_acyclic = acyclic.getEdge()[x].getFrom();
        int edgeTo_acyclic = acyclic.getEdge()[x].getTo();
        // look for mismatch
        if ((edgeFrom_cyclic != edgeFrom_acyclic) && (edgeTo_cyclic != edgeTo_acyclic)) {
            this.minFES_new.add(new robert.sheridan.algorithm.Edge(edgeTo_acyclic, edgeFrom_acyclic));
        }
    }
    // reconstruct
    this.a_edge = new robert.sheridan.algorithm.Edge[this.minFES_new.size()];
    int index = 0;
    for (robert.sheridan.algorithm.Edge e : this.minFES_new) {
        this.a_edge[index++] = e;
    }
    this.mFES_new = this.minFES_new.size();
    if (this.mFES == 0) {
        this.mFES = this.mFES_new;
        for (robert.sheridan.algorithm.Edge e : this.minFES_new) {
            this.minFES.add(new robert.sheridan.algorithm.Edge(e.getFrom(), e.getTo()));
        }
    }
}

