public void runDominationStability() {
    java.lang.System.out.println("Domination Stability Benchmark");
    java.util.Map<java.lang.String, java.io.File> all = this.getAll();
    java.util.Map<java.lang.String, java.io.File> supers = this.getSupers();
    for (java.lang.String key : all.keySet()) {
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> allMap = new melton.hayden.jepends.analysis.EqualityByReferenceMapGenerator<java.lang.String>(melton.hayden.jepends.analysis.MapFileParser.parse(all.get(key))).getMap();
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> superMap = new melton.hayden.jepends.analysis.EqualityByReferenceMapGenerator<java.lang.String>(melton.hayden.jepends.analysis.MapFileParser.parse(supers.get(key))).getMap();
        melton.hayden.jepends.algorithm.ttcormenetal.CLR90SCC<java.lang.String> sccGenerator = new melton.hayden.jepends.algorithm.ttcormenetal.CLR90SCC<java.lang.String>(allMap);
        sccGenerator.run();
        long before = java.lang.System.currentTimeMillis();
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> edgeRemoveMapIntersection = new java.util.HashMap<java.lang.String, java.util.Set<java.lang.String>>();
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> allRemoveMap = new java.util.HashMap<java.lang.String, java.util.Set<java.lang.String>>();
        for (int i = 0; i < 5000; i++) {
            java.util.Map<java.lang.String, java.util.Set<java.lang.String>> edgeRemoveMap = new java.util.HashMap<java.lang.String, java.util.Set<java.lang.String>>();
            java.util.List<java.util.Set<java.lang.String>> sccs = sccGenerator.getSCCs();
            for (java.util.Set<java.lang.String> set : sccs) {
                if (set.size() == 1) {
                    continue;
                }
                java.util.Map<java.lang.String, java.util.Set<java.lang.String>> culledAllMap = this.cullMap(allMap, set);
                java.util.Map<java.lang.String, java.util.Set<java.lang.String>> culledSuperMap = this.cullMap(superMap, set);
                melton.hayden.jepends.analysis.FeedbackSetHeuristic feedbackSetHeuristic = new melton.hayden.jepends.analysis.FeedbackSetHeuristic(culledAllMap, culledSuperMap);
                feedbackSetHeuristic.run(new java.util.Random(i), true);
                java.util.Map<java.lang.String, java.util.Set<java.lang.String>> m = feedbackSetHeuristic.getEdgesToRemove();
                edgeRemoveMap.putAll(m);
            }
            // System.out.println(edgeRemoveMap.size());
            if (i == 0) {
                edgeRemoveMapIntersection = edgeRemoveMap;
            }
            edgeRemoveMapIntersection = this.intersection(edgeRemoveMap, edgeRemoveMapIntersection);
            // System.out.print(edgeRemoveMapIntersection.size()+" ");
            allRemoveMap = this.merge(allRemoveMap, edgeRemoveMap);
        }
        long after = java.lang.System.currentTimeMillis();
        long diff = after - before;
        int intersection = 0;
        for (java.util.Set<java.lang.String> set : edgeRemoveMapIntersection.values()) {
            intersection += set.size();
        }
        int count = 0;
        for (java.util.Set<java.lang.String> set : allRemoveMap.values()) {
            count += set.size();
        }
        java.lang.System.out.println((((key + "\t") + intersection) + "\t") + count);
    }
    java.lang.System.out.println();
    // System.out.println();
}

