public void simulateOthers(java.util.List<java.lang.String> sources, java.util.List<java.lang.String> targets, java.util.List<java.lang.String> decision) {
    this.initializeMaps();
    long startTime = java.lang.System.currentTimeMillis();
    java.util.Set<java.lang.String> sources_ = new java.util.HashSet<java.lang.String>(sources);
    this.candidatesCRSS = new java.util.HashMap<java.lang.String, tosin.oyetoyan.refsimulator.support.SCCCRSSData>();
    // get the sources and their pre-refactoring crss values
    this.computePrePostCRSS(sources_, true);
    this.refactoredEdges = new java.util.ArrayList<tosin.oyetoyan.refsimulator.support.RefactoredEdges>();
    this.fitness = new tosin.oyetoyan.refsimulator.support.fitness.FitnessValuesOthers();
    // fitness - pre refactoring
    this.fitnessSCC(this.map, true);
    this.fitnessHistogram(this.map, true);
    java.util.List<java.lang.Double> postFitMean = new java.util.ArrayList<java.lang.Double>();
    java.util.List<java.lang.Double> postFitStdDev = new java.util.ArrayList<java.lang.Double>();
    java.lang.Double[] fit = new java.lang.Double[2];
    this.fitnessFunction(this.map, fit);// fitness function for map before refactoring

    this.fitness.setPreRefactoring_Mean(fit[0]);
    this.fitness.setPreRefactoring_StdDev(fit[1]);
    this.fitness.setPreRefactoringNumberOfComponents(this.map.keySet().size());
    this.fitness.setPreRefactoringNumberOfEdges(this.calcOfEdges());
    tosin.oyetoyan.refsimulator.support.DecisionSupportTable2 dst2 = new tosin.oyetoyan.refsimulator.support.DecisionSupportTable2();
    // iterate over each edge
    for (int i = 0; i < sources.size(); i++) {
        tosin.oyetoyan.refsimulator.support.Table2Schema s = dst2.getEdgeSchema(sources.get(i), targets.get(i));
        if (decision.get(i).equals(tosin.oyetoyan.refsimulator.support.Strategy.EI) || decision.get(i).equals(tosin.oyetoyan.refsimulator.support.Strategy.EA)) {
            java.lang.String interfaze = targets.get(i) + "_Interface";
            this.dependencyInjection(sources.get(i), targets.get(i), interfaze, dst2);
        }
        if (decision.get(i).equals(tosin.oyetoyan.refsimulator.support.Strategy.CF)) {
            this.refactorCopyStaticFinalField(sources.get(i), targets.get(i), s);
        }
        if (decision.get(i).equals(tosin.oyetoyan.refsimulator.support.Strategy.IM)) {
            this.refactorInlineStaticMethod(sources.get(i), targets.get(i), s);
        }
        if (decision.get(i).equals(tosin.oyetoyan.refsimulator.support.Strategy.SR)) {
            java.lang.String interfaze = targets.get(i) + "_Interface";
            this.registry(sources.get(i), targets.get(i), interfaze, dst2, true);
        }
        if (decision.get(i).equals(tosin.oyetoyan.refsimulator.support.Strategy.PR)) {
            java.lang.String interfaze = targets.get(i) + "_Interface";
            this.registry(sources.get(i), targets.get(i), interfaze, dst2, false);
        }
    }
    long endTime = java.lang.System.currentTimeMillis() - startTime;
    this.fitness.setRuntime(endTime);
    // now add fitness of refactoring
    fit = new java.lang.Double[2];
    this.fitnessFunction(this.map, fit);// fitness function for map after refactoring

    postFitMean.add(fit[0]);
    postFitStdDev.add(fit[1]);
    this.fitness.setPostRefactoring_Mean(postFitMean);
    this.fitness.setPostRefactoring_StdDev(postFitStdDev);
    this.fitness.setPostRefactoringNumberOfComponents(this.map.keySet().size());
    this.fitness.setPostRefactoringNumberOfEdges(this.calcOfEdges());
    // fitness - post refactoring
    this.fitnessSCC(this.map, false);
    this.fitnessHistogram(this.map, false);
    this.setDsTable2(dst2);
    // get the sources and their post-refactoring crss values
    this.computePrePostCRSS(sources_, false);
    // update maps
    this.updateMapsAfterRefactoring();
}

