private void contextData(java.util.Set<java.lang.String> fanouts, tosin.oyetoyan.refsimulator.support.Table2Schema s) {
    // Map<String, Integer> fancrss = new HashMap<String, Integer>();
    java.lang.String source = s.getSource();
    java.util.List<java.lang.String> depends = new java.util.ArrayList<java.lang.String>();
    for (java.lang.String f : fanouts) {
        depends.add(f);
    }
    // ****usage types for each edge
    if (fanouts.size() == 0) {
        // no target class. i.e. no dependency
        s.setTarget("");
        s.setStatic(false);
        s.setIsInterface(false);
        s.setIsAbstract(false);
        s.setFanin(s.getFanin());
        s.setFanouts(0);
        tosin.oyetoyan.refsimulator.support.ClassUsesTypes uses = new tosin.oyetoyan.refsimulator.support.ClassUsesTypes();
        s.setUsageTypes(uses);
        s.setDecision(tosin.oyetoyan.refsimulator.support.Strategy.NONE);
        s.getDecision_Set().add(tosin.oyetoyan.refsimulator.support.Strategy.NONE);
        this.dsTable2_lookUp.add(s);
    } else {
        for (int i = 0; i < fanouts.size(); i++) {
            java.lang.String target = depends.get(i);
            tosin.oyetoyan.refsimulator.support.Table2Schema edge = new tosin.oyetoyan.refsimulator.support.Table2Schema();
            edge.setSource(s.getSource());
            edge.setTarget(target);
            edge.setFanouts(s.getFanouts());
            edge.setFanin(s.getFanin());
            // ****usage types****
            tosin.oyetoyan.refsimulator.support.ClassUsesTypes uses = new tosin.oyetoyan.refsimulator.support.ClassUsesTypes();
            // fanins to Target
            edge.setDependsFanin(this.mapT.get(target).size());
            // Target isStatic
            boolean ztatic = true;
            try {
                if (this.membersAccessMap.get(target).contains("nonstatic")) {
                    ztatic = false;
                }
            } catch (java.lang.Exception e) {
                ztatic = false;
            }
            edge.setStatic(ztatic);
            // Target isInterface
            boolean isIface = false;
            try {
                isIface = this.classTypesmap.get(target).contains("I");
            } catch (java.lang.Exception e) {
            }
            edge.setIsInterface(isIface);
            // Target isAbstract
            boolean isAbstract = false;
            try {
                isAbstract = this.classTypesmap.get(target).contains("A");
            } catch (java.lang.Exception e) {
            }
            edge.setIsAbstract(isAbstract);
            // interface uses
            if (this.interfaceTypesMap.containsKey(source)) {
                if (this.interfaceTypesMap.get(source).contains(target)) {
                    uses.setInterfaceType(true);
                }
            }
            // supertype uses
            if (this.superTypesMap.containsKey(source)) {
                if (this.superTypesMap.get(source).contains(target)) {
                    uses.setSuperType(true);
                    // supertype uses where super class is an abstract class
                    uses.setAbstractUses(isAbstract);// special

                }
            }
            // field declaration uses
            if (this.fieldDeclarationMap.containsKey(source)) {
                if (this.fieldDeclarationMap.get(source).contains(target)) {
                    uses.setFieldDeclaration(true);
                }
            }
            // static field invocation uses
            if (this.staticFieldInvokeMap.containsKey(source)) {
                if (this.staticFieldInvokeMap.get(source).contains(target)) {
                    uses.setStaticFieldInvoke(true);
                }
            }
            // static final field invocation uses
            if (this.staticFinalFieldInvokeMap.containsKey(source)) {
                if (this.staticFinalFieldInvokeMap.get(source).contains(target)) {
                    uses.setStaticFinalFieldInvoke(true);
                }
            }
            // method return type uses
            if (this.methodReturnMap.containsKey(source)) {
                if (this.methodReturnMap.get(source).contains(target)) {
                    uses.setMethodReturn(true);
                }
            }
            // method exception type uses
            if (this.methodExceptionMap.containsKey(source)) {
                if (this.methodExceptionMap.get(source).contains(target)) {
                    uses.setMethodException(true);
                }
            }
            // method parameter type uses
            if (this.methodParameterMap.containsKey(source)) {
                if (this.methodParameterMap.get(source).contains(target)) {
                    uses.setMethodParameter(true);
                }
            }
            // static method invocation uses
            if (this.staticMethodInvokeMap.containsKey(source)) {
                if (this.staticMethodInvokeMap.get(source).contains(target)) {
                    uses.setStaticMethod(true);
                }
            }
            // constructor invocation uses
            if (this.constructorInvokeMap.containsKey(source)) {
                if (this.constructorInvokeMap.get(source).contains(target)) {
                    uses.setConstructorInvoke(true);
                }
            }
            // other uses
            if (this.otherUsesTypesMap.containsKey(source)) {
                if (this.otherUsesTypesMap.get(source).contains(target)) {
                    uses.setOtherType(true);
                }
            }
            edge.setUsageTypes(uses);
            edge.processDecision();// determine the strategy to break the dependency btw source & target class

            // add each edge data
            this.dsTable2_lookUp.add(edge);
        }
    }
}

