private void sortList(java.lang.Object[] sortedL, int type) {
    // 1. sort in ascending/descending order
    // 2. preserve the original index of the array
    // Object[] sortedL = data.toArray();
    java.lang.Object temp;// needs a temp storage

    java.lang.Object indx;
    java.lang.Object[] sortedI = new java.lang.Object[sortedL.length];
    for (int i = 0; i < sortedL.length; i++) {
        sortedI[i] = i;
    }
    for (int i = 0; i < sortedL.length; i++) {
        int k = i + 1;
        for (int j = k; j < sortedL.length; j++) {
            double dit1 = java.lang.Double.valueOf(sortedL[i].toString());
            double dit2 = java.lang.Double.valueOf(sortedL[j].toString());
            if (type == tosin.oyetoyan.refsimulator.utility.Sort.DESCENDING) {
                if (dit1 < dit2) {
                    // swap to sort
                    temp = sortedL[j];
                    sortedL[j] = sortedL[i];
                    sortedL[i] = temp;
                    indx = sortedI[j];
                    sortedI[j] = sortedI[i];
                    sortedI[i] = indx;
                }
            }
            if (type == tosin.oyetoyan.refsimulator.utility.Sort.ASCENDING) {
                if (dit1 > dit2) {
                    // swap to sort
                    temp = sortedL[j];
                    sortedL[j] = sortedL[i];
                    sortedL[i] = temp;
                    indx = sortedI[j];
                    sortedI[j] = sortedI[i];
                    sortedI[i] = indx;
                }
            }
        }
    }
    this.setSortedList(sortedL);
    this.setIndex(sortedI);
}

