private void dscc(java.util.Map<java.lang.String, java.util.Set<java.lang.String>> map, java.util.Map<java.lang.String, java.util.List<java.lang.String>> outMap, java.util.List<java.util.Set<java.lang.String>> sccs) {
    this.dependOnSCC = new java.util.HashMap<java.lang.String, java.util.Set<java.lang.String>>();
    outMap.get("class").add("dscc");
    for (java.lang.String key : map.keySet()) {
        java.util.Set<java.lang.String> fanout_bk = map.get(key);
        int last = outMap.get(key).size() - 1;
        java.lang.String scc = outMap.get(key).get(last);
        java.util.Set<java.lang.String> fanout_final = new java.util.HashSet<java.lang.String>();
        this.copySet(fanout_bk, fanout_final);
        int numdscc = 0;
        if (scc.equals("0")) {
            java.util.Set<java.lang.String> fanout = new java.util.HashSet<java.lang.String>();// copy set in a non-destructive way

            this.copySet(fanout_bk, fanout);
            for (java.util.Set<java.lang.String> set : sccs) {
                if ((set.size() > 1) && (fanout.size() > 0)) {
                    fanout.removeAll(set);// (fanout - set)

                }
            }
            numdscc = fanout_bk.size() - fanout.size();
            if (numdscc > 0) {
                fanout_final.removeAll(fanout);
                this.dependOnSCC.put(key, fanout_final);
            } else {
                this.dependOnSCC.put(key, new java.util.HashSet<java.lang.String>());
            }
        } else {
            this.dependOnSCC.put(key, new java.util.HashSet<java.lang.String>());
        }
        outMap.get(key).add(numdscc + "");
    }
}

