private void dfs(K key) {
    if (this.visited.contains(key)) {
        return;
    }
    this.path.add(key);
    this.trees.getLast().add(key);
    this.visited.add(key);
    this.timestamp++;
    this.discoveredMap.put(key, this.timestamp);
    java.util.Set<K> neighbours = this.map.get(key);
    for (K k : neighbours) {
        this.dfs(k);
    }
    this.timestamp++;
    this.finishedMap.put(key, this.timestamp);
    K last = this.path.removeLast();
    // sanity check
    if (last != key) {
        throw new java.lang.RuntimeException("something faulty in my logic");
    }
}

