public int[] componentIndex() {
    int cI[] = new int[this.nodecount];
    java.util.LinkedList componentNode[] = new java.util.LinkedList[this.nodecount];
    int x;
    for (x = 0; x < this.nodecount; x++) {
        cI[x] = x;
        componentNode[x] = new java.util.LinkedList();
        componentNode[x].add(new java.lang.Integer(x));
    }
    for (x = 0; x < this.edge.length; x++) {
        if (cI[this.edge[x].getFrom()] != cI[this.edge[x].getTo()]) {
            /* merge components */
            int smaller = cI[this.edge[x].getFrom()];
            int larger = cI[this.edge[x].getTo()];
            if (smaller > larger) {
                int tmp = smaller;
                smaller = larger;
                larger = tmp;
            }
            java.util.Iterator iter = componentNode[larger].iterator();
            while (iter.hasNext()) {
                int nodeIndex = ((java.lang.Integer) (iter.next())).intValue();
                cI[nodeIndex] = smaller;
                componentNode[smaller].add(new java.lang.Integer(nodeIndex));
            } 
        }
    }
    /* make index numbers contiguous */
    int contiguousMap[] = new int[this.nodecount];
    int topSeen = 0;
    int topAssigned = 0;
    for (x = 0; x < this.nodecount; x++) {
        if (cI[x] > topSeen) {
            topSeen = cI[x];
            contiguousMap[cI[x]] = ++topAssigned;
        }
        cI[x] = contiguousMap[cI[x]];
    }
    return cI;
}

