                // k = Integer.compare(o2.scc_to, o1.scc_to);
            }
            if (sortPriority.equals(tosin.oyetoyan.refsimulator.support.DecisionSupportCycles.REDUCEDRATE)) {
                k = java.lang.Integer.compare(o2.fanin_from, o1.fanin_from);// descending order

                j = java.lang.Double.compare(o2.reducedBy, o1.reducedBy);
            }
            int retStatus = 0;
            if (j < 0) {
                retStatus = -1;
            } else if (j > 0) {
                retStatus = 1;
            } else if (k < 0) {
                retStatus = -1;
            } else if (k > 0) {
