public void loadData(java.util.List<java.lang.Object> data, java.lang.String dataType) {
    this.histogram = new java.util.ArrayList<tosin.oyetoyan.refsimulator.support.graph.Histogram.Hist>();
    // find minimum and maximum
    java.lang.Double max = 0.0;
    // Double min = 0.0;
    java.util.List<java.lang.Double> d = new java.util.ArrayList<java.lang.Double>();
    if (dataType.equals(tosin.oyetoyan.refsimulator.support.graph.Graph.DOUBLE)) {
        double mx = 0.0;
        double mn = java.lang.Double.MAX_VALUE;
        for (java.lang.Object o : data) {
            double v = java.lang.Double.valueOf(o.toString());
            mx = java.lang.Math.max(mx, v);
            mn = java.lang.Math.min(mn, v);
            d.add(v);
        }
        max = mx;
        // min = mn;
    }
    // 
    if (dataType.equals(tosin.oyetoyan.refsimulator.support.graph.Graph.INTEGER)) {
        int mx = 0;
        int mn = java.lang.Integer.MAX_VALUE;
        for (java.lang.Object o : data) {
            int v = java.lang.Integer.valueOf(o.toString());
            mx = java.lang.Math.max(mx, v);
            mn = java.lang.Math.min(mn, v);
            d.add(((double) (v)));
        }
        max = ((double) (mx));
        // min = (double) mn;
    }
    // sort
    java.util.Collections.<java.lang.Double>sort(d, new java.util.Comparator<java.lang.Double>() {
        1() {
            super();
        }

        @java.lang.Override
        public int compare(java.lang.Double o1, java.lang.Double o2) {
            return java.lang.Double.compare(o1, o2);
        }
    });
    // generate the interval
    int i = 0;
    do {
        // range.add(new Range(i+1,i+interval));
        int count = 0;
        // go over sorted list
        int upper = i + this.interval;
        for (int j = 0; j < d.size(); j++) {
            double v = d.get(j);
            if ((v >= (i + 1)) && (v <= upper)) {
                count++;
            }
        }
        // add to map
        int lower = i + 1;
        java.lang.String range = (lower + "-") + upper;
        this.histogram.add(new tosin.oyetoyan.refsimulator.support.graph.Histogram.Hist(range, count));
        // delete added data from list
        /* if(count > 0)
        for(int k=0; k<count; k++)
        d.remove(k);
         */
        // increase by interval
        i += this.interval;
    } while (i < (max + this.interval) );
}

