private void updateMapsForInterfaceUses(java.lang.String interfaze, java.lang.String target, java.util.Set<java.lang.String> publishedTypes, tosin.oyetoyan.refsimulator.support.DecisionSupportTable2 dst2) {
    this.updateInterface(interfaze);
    java.util.Set<java.lang.String> _map = this.map.get(interfaze);
    for (java.lang.String published : publishedTypes) {
        _map.add(published);
    }
    this.ptMap.put(interfaze, publishedTypes);
    // create dependency from target -> interface
    this.map.get(target).add(interfaze);
    // implements
    this.interfaceMap.get(target).add(interfaze);// implements

    // update DSTable2
    this.setDSTable2Maps(dst2);
    dst2.updateTable(this.map);
    // check how the source uses the target to determine how source uses Itarget
    // 4 maps are of interest here: fMap, mpMap, mrMap, meMap
    java.util.Map<java.lang.String, java.lang.Boolean> done = new java.util.HashMap<java.lang.String, java.lang.Boolean>();// use to track whether edge to refactor is already created

    for (java.lang.String _target : publishedTypes) {
        done.put(_target, false);
    }
    for (java.lang.String _target : publishedTypes) {
        tosin.oyetoyan.refsimulator.support.Table2Schema s = dst2.getEdgeSchema(target, _target);
        if (!done.get(_target)) {
            this.refactoredEdges.add(new tosin.oyetoyan.refsimulator.support.RefactoredEdges(interfaze, _target, tosin.oyetoyan.refsimulator.support.ModelSimulator.USES, tosin.oyetoyan.refsimulator.support.ModelSimulator.DECLAREMETHOD));
            done.put(_target, true);
        }
        if (s.getUsageTypes().isStaticFinalFieldInvoke()) {
            java.util.Set<java.lang.String> d = new java.util.HashSet<java.lang.String>();
            d.add(_target);
            this.fMap.put(interfaze, d);// now interface depends on target through variable decl.

            // refactoredEdges.add(new RefactoredEdges(interfaze, _target, USES, MOVEFIELD));
        }
        if (s.getUsageTypes().isMethodParameter()) {
            java.util.Set<java.lang.String> d = new java.util.HashSet<java.lang.String>();
            d.add(_target);
            this.mpMap.put(interfaze, d);// now interface depends on target in its method parameter.

            // refactoredEdges.add(new RefactoredEdges(interfaze, _target, USES, DECLAREMETHOD));
        }
        if (s.getUsageTypes().isMethodReturn()) {
            java.util.Set<java.lang.String> d = new java.util.HashSet<java.lang.String>();
            d.add(_target);
            this.mrMap.put(interfaze, d);// now interface depends on target in its method return.

            // refactoredEdges.add(new RefactoredEdges(interfaze, _target, USES, DECLAREMETHOD));
        }
        if (s.getUsageTypes().isMethodException()) {
            java.util.Set<java.lang.String> d = new java.util.HashSet<java.lang.String>();
            d.add(_target);
            this.meMap.put(interfaze, d);// now interface depends on target in its method exception.

            // refactoredEdges.add(new RefactoredEdges(interfaze, _target, USES, DECLAREMETHOD));
        }
    }
}

