        maxscc = java.lang.Math.max(maxscc, scc.size());
        sm.addValue(scc.size());
    }
    // set fitness
    if (pre) {
        this.fitness.setPreRefactoring_MinSCCSize(minscc);
        this.fitness.setPreRefactoring_MaxSCCSize(maxscc);
        this.fitness.setPreRefactoringNumOfSCCs(analyse.getSccs().size());
        this.fitness.setPreRefactoring_MeanSCC(sm.getMean());
    } else {
        // post
        this.fitness.setPostRefactoring_MinSCCSize(minscc);
        this.fitness.setPostRefactoring_MaxSCCSize(maxscc);
        this.fitness.setPostRefactoringNumOfSCCs(analyse.getSccs().size());
        this.fitness.setPostRefactoring_MeanSCC(sm.getMean());
    }
}

