        while ((str = in.readLine()) != null) {
            java.lang.String trimmed = str.trim();
            java.lang.String[] split = trimmed.split("\t");
            java.lang.String key = split[0];
            str = str.substring(key.length(), str.length());
            if (retMap.containsKey(key)) {
                java.util.Map<java.lang.String, java.util.Set<java.lang.String>> ret = retMap.get(key);
                melton.hayden.jepends.analysis.MapFileParser.processInnerMap(str, ret);
                retMap.put(key, ret);
            } else {
                java.util.Map<java.lang.String, java.util.Set<java.lang.String>> ret = new java.util.HashMap<java.lang.String, java.util.Set<java.lang.String>>();
                melton.hayden.jepends.analysis.MapFileParser.processInnerMap(str, ret);
                retMap.put(key, ret);
            }
        } 
        in.close();
    } catch (java.io.IOException e) {
        throw new java.lang.RuntimeException(e);
    }
    return retMap;
}

