public void preSimulation(int n, double IRCRSS1, double IRCRSS2) {
    long startTime = java.lang.System.currentTimeMillis();
    this.initializeMaps();
    this.fitness = new tosin.oyetoyan.refsimulator.support.fitness.FitnessValuesSystem();
    this.selectedCand = new java.util.ArrayList<java.lang.String>();
    this.fitnessSCC(this.map, true);
    // first Table-1
    tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1 fed = new tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1(this.map, this.ptMap, this.mtMap, this.tMap, this.sortPriority);
    // now simulate
    for (int i = 0; i < n; i++) {
        // make copies-1
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> copy1Map = tosin.oyetoyan.refsimulator.utility.CreateMap.copy(this.map);// to restore back

        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> copy1PtMap = tosin.oyetoyan.refsimulator.utility.CreateMap.copy(this.ptMap);
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> copy1tMap = tosin.oyetoyan.refsimulator.utility.CreateMap.copy(this.tMap);
        // make copies-2
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> copy2Map = tosin.oyetoyan.refsimulator.utility.CreateMap.copy(this.map);// to restore back

        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> copy2PtMap = tosin.oyetoyan.refsimulator.utility.CreateMap.copy(this.ptMap);
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> copy2tMap = tosin.oyetoyan.refsimulator.utility.CreateMap.copy(this.tMap);
        // update table-1 for copies-1
        fed.updateTable(copy1Map, copy1PtMap, this.mtMap, copy1tMap);
        fed.processCandidates(this.topKcrss, this.topKscc, this.topKfanin, IRCRSS1);
        java.util.List<tosin.oyetoyan.refsimulator.support.DiffExtractInterface> candidates = this.getCandidates(fed);
        if (candidates.size() == 0) {
            break;
        }
        tosin.oyetoyan.refsimulator.support.DiffExtractInterface ei = candidates.get(0);
        java.lang.String cand1 = ei.getComp();
        int fanin1 = ei.getFanin();
        this.runPre(ei, copy1Map, copy1PtMap, copy1tMap);
        // get fitness-1
        int maxscc1 = this.fitness.getPostRefactoring_MaxSCCSize();
        double meanscc1 = this.fitness.getPostRefactoring_MeanSCC();
        java.lang.System.out.println(((((("MaxSCC1 " + "\t") + maxscc1) + "\t") + i) + "\t") + cand1);
        // perform the same simulation for the second selected candidate
        // update table-1 for copies-2
        fed.updateTable(copy2Map, copy2PtMap, this.mtMap, copy2tMap);
        fed.processCandidates(this.topKcrss, this.topKscc, this.topKfanin, IRCRSS2);
        candidates = this.getCandidates(fed);
        if (candidates.size() == 0) {
            break;
        }
        ei = candidates.get(0);
        java.lang.String cand2 = ei.getComp();
        // int sccsize2 = ei.getSccSize();
        int fanin2 = ei.getFanin();
        this.runPre(ei, copy2Map, copy2PtMap, copy2tMap);
        // get fitness-2
        int maxscc2 = this.fitness.getPostRefactoring_MaxSCCSize();
        double meanscc2 = this.fitness.getPostRefactoring_MeanSCC();
        java.lang.System.out.println(((((("MaxSCC2 " + "\t") + maxscc2) + "\t") + i) + "\t") + cand2);
        // compare both and select the better fit candidate
        // && sccsize1 >= sccsize2
        double fanRatio = ((double) (fanin1 - fanin2)) / fanin1;
        // System.out.println(fanRatio);
        // here prioritize ircrss=0 if no difference with ircrss > 0
        if ((maxscc1 < maxscc2) || ((fanRatio >= this.faninRatio) || (fanRatio == 0))) {
            this.map = copy1Map;
            this.ptMap = copy1PtMap;
            this.tMap = copy1tMap;
            // final candidate refactored
            this.selectedCand.add(cand1);
            this.fitness.setPostRefactoring_MaxSCCSize(maxscc1);
            this.fitness.setPostRefactoring_MeanSCC(meanscc1);
        } else {
            // if(maxscc2 <= maxscc1)
            this.map = copy2Map;
            this.ptMap = copy2PtMap;
            this.tMap = copy2tMap;
            // final candidate refactored
            this.selectedCand.add(cand2);
            this.fitness.setPostRefactoring_MaxSCCSize(maxscc2);
            this.fitness.setPostRefactoring_MeanSCC(meanscc2);
        }
    }
    this.finalCand = this.selectedCand;
    long endTime = java.lang.System.currentTimeMillis() - startTime;
    this.fitness.setRuntime(endTime);
    // System.out.println("pre-Runtime: "+endTime);
}

