public void findDiameterAndRadius() {
    // Find the diameter from the shortest distance of all pairs (geodesic).
    int maximum = this.pathdistance[0][0];
    java.util.List<java.lang.Integer> storeRowMax = new java.util.ArrayList<java.lang.Integer>();
    for (int i = 0; i < this.graph.length; i++) {
        int ecmax = this.pathdistance[i][0];// initialize with the first element in the row (node)

        for (int j = 0; j < this.graph.length; j++) {
            maximum = java.lang.Math.max(maximum, this.pathdistance[i][j]);// Diameter - Maximum of the geodesic

            ecmax = java.lang.Math.max(ecmax, this.pathdistance[i][j]);
            // System.out.print(shortpath[i][j]+" ");
        }
        storeRowMax.add(ecmax);// store the eccentricity of each node

        // System.out.println();
    }
    // find the radius from the eccentricities
    int minimum = storeRowMax.get(0);
    for (int m : storeRowMax) {
        minimum = java.lang.Math.min(minimum, m);
    }
    this.diameter = maximum;
    this.radius = minimum;
}

