public void processCandidates(int topKcrss, int topKscc, int topKfanin, double reducedBy) {
    // needs a rule for like 70percentile or so, we sort in descending order of
    // 1a. scc
    // 1b. crss values and select the crss value of the element at the top-k%
    // 2. fanin values and select the fanin value of the element at the top-k%
    // 3. the percent decrease between the crss and refactored crss must be higher than average (e.g.)
    int ruleScc = this.percentile(topKscc, tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.SCC);
    int ruleCrss = this.percentile(topKcrss, tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.CRSS);
    int ruleFanin = this.percentile(topKfanin, tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.FANIN);
    tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.minFanin = java.lang.Double.MAX_VALUE;
    tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.maxFanin = 0.0;
    for (tosin.oyetoyan.refsimulator.support.DiffExtractInterface dei : tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.dsTable1) {
        // candidate must not be an interface or abstract type because those can not be instantiated
        if ((((((dei.getSccSize() >= ruleScc) && (dei.getCrss() >= ruleCrss)) && (dei.getFanin() >= ruleFanin)) && (dei.getPercentDecreaseCRSS() >= reducedBy)) && (!dei.isInterface())) && (!dei.isAbstract())) {
            this.candidates.add(dei);
            tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.minFanin = java.lang.Math.min(tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.minFanin, dei.getFanin());
            tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.maxFanin = java.lang.Math.max(tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.maxFanin, dei.getFanin());
        }
    }
    this.sortCollection(this.candidates, tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.sortPriority);
}

