public java.util.Map<java.lang.String, java.util.Set<java.lang.String>> getMap() {
    java.util.Map<java.lang.String, java.util.Set<java.lang.String>> mergedMap = new java.util.HashMap<java.lang.String, java.util.Set<java.lang.String>>();
    for (java.lang.String clazz : this.map.keySet()) {
        java.lang.String top = melton.hayden.jepends.clean.TopLevelClassMerger.toTopLevel(clazz);
        mergedMap.put(top, new java.util.HashSet<java.lang.String>());
    }
    for (java.lang.String clazz : this.map.keySet()) {
        java.lang.String top = melton.hayden.jepends.clean.TopLevelClassMerger.toTopLevel(clazz);
        java.util.Set<java.lang.String> oldSet = this.map.get(clazz);
        java.util.Set<java.lang.String> newSet = mergedMap.get(top);
        for (java.lang.String string : oldSet) {
            java.lang.String topLevelDep = melton.hayden.jepends.clean.TopLevelClassMerger.toTopLevel(string);
            if (this.map.keySet().contains(topLevelDep)) {
                newSet.add(topLevelDep);
            } else {
                this.missingClasses.add(topLevelDep);
            }
        }
    }
    for (java.lang.String clazz : mergedMap.keySet()) {
        java.util.Set<java.lang.String> newSet = mergedMap.get(clazz);
        // disallow self-references
        newSet.remove(clazz);
    }
    return java.util.Collections.<java.lang.String, java.util.Set<java.lang.String>>unmodifiableMap(mergedMap);
}

