private java.util.Map<java.lang.String, java.util.Set<java.lang.String>> merge(java.util.Map<java.lang.String, java.util.Set<java.lang.String>> left, java.util.Map<java.lang.String, java.util.Set<java.lang.String>> right) {
    java.util.Map<java.lang.String, java.util.Set<java.lang.String>> map = new java.util.HashMap<java.lang.String, java.util.Set<java.lang.String>>();
    for (java.lang.String k : left.keySet()) {
        java.util.Set<java.lang.String> copy = new java.util.HashSet<java.lang.String>(left.get(k));
        map.put(k, copy);
    }
    for (java.lang.String k : right.keySet()) {
        java.util.Set<java.lang.String> copy = map.get(k);
        if (copy == null) {
            copy = new java.util.HashSet<java.lang.String>();
            map.put(k, copy);
        }
        copy.addAll(right.get(k));
    }
    return map;
}

