public int run(java.util.Random random, boolean b) {
    this.edgesToRemove.clear();
    java.util.LinkedList<java.lang.String> ll = new java.util.LinkedList<java.lang.String>();
    ll.addAll(this.map.keySet());
    // start with a deterministic alphabetical ordering
    java.util.Collections.<java.lang.String>sort(ll);
    // ok need to make this deterministic
    if (random != null) {
        java.util.Collections.shuffle(ll, random);
    }
    if (b) {
        java.util.Collections.<java.lang.String>sort(ll, this.comparator);
    } else {
        java.util.Collections.<java.lang.String>sort(ll, this.inverseComparator);
    }
    // System.out.println(ll);
    int count = 0;
    java.util.Set<java.lang.String> visited = new java.util.HashSet<java.lang.String>();
    for (java.lang.String key : ll) {
        java.util.Set<java.lang.String> set = this.map.get(key);
        for (java.lang.String k : set) {
            if (visited.contains(k)) {
                // remove edge
                count++;
                // Set<String> removalSet = edgesToRemove.get(key);
                java.util.Set<java.lang.String> removalSet = this.edgesToRemove.get(key);
                if (removalSet == null) {
                    removalSet = new java.util.HashSet<java.lang.String>();
                    this.edgesToRemove.put(key, removalSet);
                }
                removalSet.add(k);
            }
        }
        visited.add(key);
    }
    return count;
    // System.out.println(count);
}

private void run(java.util.Map<java.lang.String, java.util.Set<java.lang.String>> map, java.util.Map<java.lang.String, java.util.Set<java.lang.String>> publishedMap, java.util.Map<java.lang.String, java.util.Set<java.lang.String>> membersAccessMap, java.util.Map<java.lang.String, java.util.Set<java.lang.String>> classTypesmap) {
    tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.dsTable1 = new java.util.LinkedList<tosin.oyetoyan.refsimulator.support.DiffExtractInterface>();
    this.candidates = new java.util.LinkedList<tosin.oyetoyan.refsimulator.support.DiffExtractInterface>();
    /*  */
    // compute the crss
    java.util.Map<java.lang.String, java.util.Set<java.lang.String>> reachabilityMap = new melton.hayden.jepends.algorithm.ReachabilityMapGenerator<java.lang.String>(map).getMap();
    // transpose map to collect fanin
    melton.hayden.jepends.algorithm.ttcormenetal.CLR90Transpose<java.lang.String> transposer = new melton.hayden.jepends.algorithm.ttcormenetal.CLR90Transpose<java.lang.String>(map);
    java.util.Map<java.lang.String, java.util.Set<java.lang.String>> mapT = transposer.getMap();
    melton.hayden.jepends.analysis.Analyser analyse = new melton.hayden.jepends.analysis.Analyser();
    analyse.analyse(map);
    java.util.Map<java.lang.String, java.util.Set<java.lang.String>> dependOnSCC = analyse.getDependOnSCC();
    // iterate over all components
    for (java.lang.String key : map.keySet()) {
        int crss = reachabilityMap.get(key).size();
        int fanin = mapT.get(key).size();
        java.util.Set<java.lang.String> fans = map.get(key);
        boolean equal = fans.equals(publishedMap.get(key));
        // handle extracted interface
        // System.out.println();
        int maxcrss_EI = 0;
        int mincrss_EI = 0;
        int numComp = 0;
        java.util.List<java.lang.String> EI = new java.util.ArrayList<java.lang.String>();
        try {
            EI = new java.util.ArrayList<java.lang.String>(publishedMap.get(key));
        } catch (java.lang.Exception e) {
            // do nothing
        }
        java.util.List<java.lang.String> compMaxCrss = new java.util.ArrayList<java.lang.String>();
        if (EI.size() > 0) {
            if (!equal) {
                maxcrss_EI = reachabilityMap.get(EI.get(0)).size();
                mincrss_EI = reachabilityMap.get(EI.get(0)).size();
                for (int i = 0; i < EI.size(); i++) {
                    maxcrss_EI = java.lang.Math.max(maxcrss_EI, reachabilityMap.get(EI.get(i)).size());
                    mincrss_EI = java.lang.Math.min(mincrss_EI, reachabilityMap.get(EI.get(i)).size());
                }
                // get the #comp with maxcrss
                for (java.lang.String ei : EI) {
                    if (reachabilityMap.get(ei).size() == maxcrss_EI) {
                        numComp++;
                        compMaxCrss.add(ei);
                    }
                }
            } else {
                maxcrss_EI = crss;// no difference between impl and iface

            }
        }// no difference between impl and iface
         else if ((fans.size() == 0) && (EI.size() == 0)) {
            maxcrss_EI = crss;
        }// no difference between impl and iface

        // scc size
        java.util.List<java.util.Set<java.lang.String>> sccs = analyse.getSccs();
        int sccSize = 0;
        int sccId = 0;
        if (sccs != null) {
            for (int i = 0; i < sccs.size(); i++) {
                java.util.Set<java.lang.String> scc = sccs.get(i);
                if (scc.contains(key)) {
                    sccSize = scc.size();
                    sccId = i + 1;
                }
            }
        }
        // check singleton or non-singleton classes
        boolean ztatic = true;
        try {
            if (membersAccessMap.get(key).contains(tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.NONSTATIC)) {
                ztatic = false;
            }
        } catch (java.lang.Exception e) {
            ztatic = false;
        }
        // check type
        boolean isIface = false;
        boolean isAbstract = false;
        try {
            isIface = classTypesmap.get(key).contains("I");
        } catch (java.lang.Exception e) {
            // System.out.println(tmap.size()+": "+ key);
        }
        try {
            isAbstract = classTypesmap.get(key).contains("A");
        } catch (java.lang.Exception e) {
            // System.out.println(tmap.size()+": "+ key);
        }
        if (isIface) {
            maxcrss_EI = crss;
        }
        boolean isDependSCC = false;
        int numDSCC = 0;
        try {
            numDSCC = dependOnSCC.get(key).size();
            isDependSCC = numDSCC > 0;
        } catch (java.lang.Exception e) {
        }
        // store
        tosin.oyetoyan.refsimulator.support.DiffExtractInterface dEI = new tosin.oyetoyan.refsimulator.support.DiffExtractInterface(key, crss, sccSize, maxcrss_EI, numComp, fanin, EI.size(), isIface);
        dEI.setSccId(sccId);
        dEI.setAbstract(isAbstract);
        dEI.setZtatic(ztatic);
        dEI.setFanout(fans.size());
        dEI.setDependOnCycle(isDependSCC);
        dEI.setNumDependOnCycle(numDSCC);
        if (numComp == 1) {
            dEI.setDcomp(compMaxCrss.get(0));
        } else {
            dEI.setDcomp("");
        }
        tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.dsTable1.add(dEI);
    }
    this.sortCollection(tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.dsTable1, tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.sortPriority);
}

