public <T extends tosin.oyetoyan.refsimulator.test.IServiceLoaderUtil> T loadService(java.lang.Class<T> service, java.lang.String implID) {
    T _loadedImpl = null;
    java.util.ServiceLoader<T> impls = java.util.ServiceLoader.<T>load(service);
    for (T loadedImpl : impls) {
        _loadedImpl = loadedImpl;
        if ((_loadedImpl != null) && loadedImpl.getImplementationID().equals(implID)) {
            break;
        }
    }
    if (_loadedImpl == null) {
        throw new java.lang.RuntimeException("Cannot find implementation for: " + service);
    }
    return _loadedImpl;
}

