public int run(java.lang.String jarDir, java.lang.String outputDir, int type) {
    boolean error = false;
    java.io.File inDir = new java.io.File(jarDir);
    if ((!inDir.exists()) || (!inDir.isDirectory())) {
        java.lang.System.out.println("[inputDir] is not a valid directory");
        error = true;
    }
    java.io.File outDir = new java.io.File(outputDir);
    if ((!outDir.exists()) || (!outDir.isDirectory())) {
        java.lang.System.out.println("[outputDir] is not a valid directory");
        error = true;
    }
    java.util.Set<java.lang.String> prefixes = new java.util.HashSet<java.lang.String>();
    if (prefixes.size() == 0) {
        // every string in java is prefixed by ""
        // ie "asdf".indexOf("") never equals -1
        prefixes.add("");
    }
    if (error) {
        return -1;
    }
    melton.hayden.jepends.bytecode.Jepends jepends = new melton.hayden.jepends.bytecode.Jepends(inDir, outDir, prefixes);
    // jepends.setProgressBar(jb);
    try {
        if (type == melton.hayden.jepends.bytecode.Jepends.CLASSDIR) {
            jepends.run(true);
        }
        if (type == melton.hayden.jepends.bytecode.Jepends.JARDIR) {
            jepends.run();
        }
        if (type == melton.hayden.jepends.bytecode.Jepends.PLUGINDIR) {
            jepends.run(this.classes);
        }
    } catch (java.lang.Throwable e) {
        e.printStackTrace();
    }
    if (type == melton.hayden.jepends.bytecode.Jepends.JARDIR) {
        this.jarName = jepends.getJarName();
    }
    melton.hayden.jepends.clean.Cleaner cleaner = new melton.hayden.jepends.clean.Cleaner(outDir);
    cleaner.run();
    melton.hayden.jepends.analysis.Analyser analyser = new melton.hayden.jepends.analysis.Analyser(outDir);
    analyser.analyse();
    return 0;
}

private java.lang.String decision(java.util.Set<java.lang.String> decisions) {
