private int registry(java.lang.String source, java.lang.String target, java.lang.String interfaze, tosin.oyetoyan.refsimulator.support.DecisionSupportTable2 dst2, boolean isSingleton) {
    // if the edge is between a source and registry/mainclass, skip
    if (target.equals(this.serviceLocator)) {
        return -1;
    }
    if (target.equals(this.mainClass)) {
        return -1;
    }
    // check to see whether the dependency still exist or has a decision
    if (!source.equals("")) {
        if (!this.map.get(source).contains(target)) {
            return -1;
        }
    }
    this.helperRefactorRegistry(target, interfaze, dst2, isSingleton);
    // update dstable2 bcos maps have changed
    this.setDSTable2Maps(dst2);
    dst2.updateTable(this.map);
    // we decide whether to use mFES only or utilize the abstraction for all dependencies
    if (this.isUseOnlyMFES()) {
        tosin.oyetoyan.refsimulator.support.Table2Schema s = dst2.getEdgeSchema(source, target);
        this.refactorRegistry(source, target, interfaze, s);
    } else {
        // refactor each edge (fanin -> target) Optimize the interface uses
        // transpose map to collect fanin
        melton.hayden.jepends.algorithm.ttcormenetal.CLR90Transpose<java.lang.String> transposer = new melton.hayden.jepends.algorithm.ttcormenetal.CLR90Transpose<java.lang.String>(this.map);
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> mapT = transposer.getMap();
        for (java.lang.String fanin : mapT.get(target)) {
            // if target is singleton and the source is mainclass, then refactoring is not possible
            /* if(isSingleton && fanin.equals(mainClass)){
            System.out.println(target+"\t"+isSingleton+"\t"+fanin+"\t"+mainClass);
            break;
            }
             */
            tosin.oyetoyan.refsimulator.support.Table2Schema s = dst2.getEdgeSchema(fanin, target);
            tosin.oyetoyan.refsimulator.support.ClassUsesTypes cut = s.getUsageTypes();
            /* if fanin is a child to target (extends/implements), just skip */
            if (cut.isInterfaceType() || cut.isSuperType()) {
                break;
            }
            if (s.getDecision().equals(tosin.oyetoyan.refsimulator.support.Strategy.PR) || s.getDecision().equals(tosin.oyetoyan.refsimulator.support.Strategy.SR)) {
                this.refactorRegistry(fanin, target, interfaze, s);
            }
            if (s.getDecision().equals(tosin.oyetoyan.refsimulator.support.Strategy.EI) || s.getDecision().equals(tosin.oyetoyan.refsimulator.support.Strategy.EA)) {
                this.refactorExtractInterface(fanin, target, interfaze, s);
            }
            if (s.getDecision().equals(tosin.oyetoyan.refsimulator.support.Strategy.IM)) {
                this.refactorInlineStaticMethod(fanin, target, s);
            }
            if (s.getDecision().equals(tosin.oyetoyan.refsimulator.support.Strategy.CF)) {
                this.refactorCopyStaticFinalField(fanin, target, s);
            }
        }
    }
    return 0;
}

