private void run(org.apache.bcel.classfile.JavaClass clazz) {
    if (clazz.isInterface()) {
        this.type = "I";
    } else if (clazz.isAbstract()) {
        this.type = "A";
    } else {
        this.type = "C";
    }
    // do the uses in size bizzo first
    melton.hayden.jepends.bytecode.UsesInSizeDependencyInferrer uisdi = new melton.hayden.jepends.bytecode.UsesInSizeDependencyInferrer(clazz);
    this.usesInSizeFieldTypes.addAll(uisdi.getUsesInSizeField());
    this.usesInSizeMethCallTypes.addAll(uisdi.getUsesInSizeMethCall());
    this.usesInMethAll.addAll(this.usesInSizeMethCallTypes);
    this.usesInSizeFieldTypesStatic.addAll(uisdi.getUsesInSizeFieldStatic());
    this.usesInSizeMethCallTypesStatic.addAll(uisdi.getUsesInSizeMethCallStatic());
    this.usesInSizeConstructorCall.addAll(uisdi.getUsesInSizeConstuctorCall());
    this.usesInSizeStaticFieldType.putAll(uisdi.getUsesInSizeFieldStaticType());
    this.typesLocation.putAll(uisdi.getTypesLocation());
    // handle constant pool
    org.apache.bcel.classfile.ConstantPool pool = clazz.getConstantPool();
    org.apache.bcel.classfile.Constant[] cs = pool.getConstantPool();
    for (int i = 0; i < cs.length; i++) {
        org.apache.bcel.classfile.Constant constant = cs[i];
        if (constant == null) {
            // do nothing
        } else if (constant instanceof org.apache.bcel.classfile.ConstantClass) {
            java.lang.String s = pool.constantToString(constant);
            this.constantPoolTypes.add(this.stripArray(s));
        }
    }
    // handle methods
    org.apache.bcel.classfile.Method[] ms = clazz.getMethods();
    for (int i = 0; i < ms.length; i++) {
        org.apache.bcel.classfile.Method method = ms[i];
        java.util.Set<java.lang.String> appropriateSet = null;
        if (!method.isPrivate()) {
            appropriateSet = this.publishedTypes;
            if (method.isStatic()) {
                java.lang.String methname = method.getName();
                this.methodTypes.add(melton.hayden.jepends.bytecode.ClassDependencyInferrer.STATIC);
                if ((methname.indexOf("$") == (-1)) && (methname.indexOf("<") == (-1))) {
                    this.staticNonPrivateMethods.add(method.getName() + method.getSignature());
                }
                if ((method.getArgumentTypes().length == 1) && method.getName().equals("main")) {
                    if (method.getArgumentTypes()[0].toString().equals("java.lang.String[]")) {
                        this.hasMain = true;
                    }
                }
            } else if (!method.getName().equals("<init>")) {
                this.methodTypes.add(melton.hayden.jepends.bytecode.ClassDependencyInferrer.NONSTATIC);
            }
        } else {
            appropriateSet = this.internalTypes;
            // added TDO
            if (method.getName().equals("<init>")) {
                this.singletonTypes.add(melton.hayden.jepends.bytecode.ClassDependencyInferrer.SINGLETON);
            }
        }
        // args
        org.apache.bcel.generic.Type[] types = method.getArgumentTypes();
        for (int j = 0; j < types.length; j++) {
            java.lang.String typeName = types[j].toString();
            java.lang.String xname = this.stripArray(typeName.toString());
            appropriateSet.add(xname);
            // added for model construction: TDO
            this.methodParameterTypes.add(xname);
            this.usesInMethAll.add(xname);// tdo

            // tdo
            if (!method.isPrivate()) {
                this.publishedTypes.add(xname);
            }
            // constructorParameterTypes
            if (method.getName().equals("<init>")) {
                this.constructorParameterTypes.add(xname);
            }
            // add the method name where the dependency is found
            java.lang.String meth = method.getName();
            if (meth.equals("<init>")) {
                meth = this.className.substring(this.className.lastIndexOf(".") + 1, this.className.length());
            }
            if (this.typesLocation.containsKey(xname)) {
                this.typesLocation.get(xname).add(meth + "()");
            } else {
                java.util.Set<java.lang.String> loc = new java.util.HashSet<java.lang.String>();
                loc.add(meth + "()");
                this.typesLocation.put(xname, loc);
            }
        }
        // ret type
        org.apache.bcel.generic.Type type = method.getReturnType();
        java.lang.String xname = this.stripArray(type.toString());
        appropriateSet.add(xname);
        this.methodReturnTypes.add(xname);
        this.usesInMethAll.add(xname);// tdo

        // tdo
        if (!method.isPrivate()) {
            this.publishedTypes.add(xname);
        }
        // add the method name where the dependency is found
        java.lang.String meth = method.getName();
        if (meth.equals("<init>")) {
            meth = this.className.substring(this.className.lastIndexOf(".") + 1, this.className.length());
        }
        if (this.typesLocation.containsKey(xname)) {
            this.typesLocation.get(xname).add(meth + "()");
        } else {
            java.util.Set<java.lang.String> loc = new java.util.HashSet<java.lang.String>();
            loc.add(meth + "()");
            this.typesLocation.put(xname, loc);
        }
        // exceptions thrown
        org.apache.bcel.classfile.ExceptionTable table = method.getExceptionTable();
        if (table != null) {
            java.lang.String[] exNames = table.getExceptionNames();
            for (java.lang.String string : exNames) {
                xname = this.stripArray(string);
                appropriateSet.add(xname);
                this.methodExceptionTypes.add(xname);// tdo from here

                this.usesInMethAll.add(xname);
                if (!method.isPrivate()) {
                    this.publishedTypes.add(xname);
                }
                // add the method name where the dependency is found
                meth = method.getName();
                if (meth.equals("<init>")) {
                    meth = this.className.substring(this.className.lastIndexOf(".") + 1, this.className.length());
                }
                if (this.typesLocation.containsKey(xname)) {
                    this.typesLocation.get(xname).add(meth + "()");
                } else {
                    java.util.Set<java.lang.String> loc = new java.util.HashSet<java.lang.String>();
                    loc.add(meth + "()");
                    this.typesLocation.put(xname, loc);
                }
            }
        }
    }
    org.apache.bcel.classfile.Field[] fs = clazz.getFields();
    for (int i = 0; i < fs.length; i++) {
        org.apache.bcel.classfile.Field field = fs[i];
        org.apache.bcel.generic.Type type = field.getType();
        java.lang.String xname = this.stripArray(type.toString());
        if (!field.isPrivate()) {
            // if(field.isFinal())		//tdo: only final field is added
            this.publishedTypes.add(xname);
            if (field.isStatic()) {
                this.staticNonPrivateFields.add(xname);
                if (field.isFinal()) {
                    this.staticNonPrivateFinalFields.add(field.getName());
                }// tdo: need the name here

            }
        }
        this.fieldTypes.add(xname);
        this.staticFields.add(xname);
        // add the name of field where the dependency is found
        if (this.typesLocation.containsKey(xname)) {
            this.typesLocation.get(xname).add(field.getName());
        } else {
            java.util.Set<java.lang.String> loc = new java.util.HashSet<java.lang.String>();
            loc.add(field.getName());
            this.typesLocation.put(xname, loc);
        }
    }
    java.lang.String supr = clazz.getSuperclassName();
    this.superTypes.add(this.stripArray(supr));
    java.lang.String[] ifaceNames = clazz.getInterfaceNames();
    for (int i = 0; i < ifaceNames.length; i++) {
        /* superTypes.add(
        stripArray(ifaceNames[i]));
         */
        this.interfaceTypes.add(this.stripArray(ifaceNames[i]));
    }
    this.cleanSets();
}

