private void trialRun(java.util.Map<java.lang.String, java.util.Set<java.lang.String>> copyMap, java.util.Map<java.lang.String, java.util.Set<java.lang.String>> copyPtMap, java.util.Map<java.lang.String, java.util.Set<java.lang.String>> mapT, java.util.Map<java.lang.String, java.util.Set<java.lang.String>> copytMap, tosin.oyetoyan.refsimulator.support.DiffExtractInterface ei) {
    // create (extract) interface of B
    java.lang.String target = ei.getComp();
    java.lang.String interfaze = target + "_Interface";
    // create dependency from target -> interface
    copyMap.get(target).add(interfaze);// implements

    copyMap.get(this.mainClass).add(target);
    java.util.Set<java.lang.String> type = new java.util.HashSet<java.lang.String>();
    type.add("I");
    copytMap.put(interfaze, type);// update tmap

    /* And add all published types of target's implementation to the interface's fanout */
    if (copyPtMap.containsKey(target)) {
        java.util.Set<java.lang.String> publishedTypes = copyPtMap.get(target);
        copyMap.put(interfaze, publishedTypes);
        copyPtMap.put(interfaze, publishedTypes);
    } else {
        copyMap.put(interfaze, new java.util.HashSet<java.lang.String>());
        copyPtMap.put(interfaze, new java.util.HashSet<java.lang.String>());
    }
    for (java.lang.String fanin : mapT.get(target)) {
        boolean isParent = false;
        try {
            isParent = this.supMap.get(fanin).contains(target);
        } catch (java.lang.Exception e) {
        }
        /* if fanin is a child to target (supers/extends) just skip */
        if (!isParent) {
            java.util.Set<java.lang.String> _map = copyMap.get(fanin);
            _map.add(interfaze);
            _map.add(this.serviceLocator);
            // remove target from fanin
            _map.remove(target);
            // update the published types map for the indegree components only if it exist in the ptmap
            try {
                java.util.Set<java.lang.String> ptmap = copyPtMap.get(fanin);
                // remove the implementation
                if (ptmap.remove(target)) {
                    ptmap.add(interfaze);
                }// replace with the interface

            } catch (java.lang.Exception e) {
            }
        }
    }
}

