public robert.sheridan.algorithm.Graph getGraphWithoutMultipleEdges() {
    java.util.LinkedList<robert.sheridan.algorithm.Edge> newEdges = new java.util.LinkedList();
    int edgeFrom;
    for (edgeFrom = 0; edgeFrom < this.nodecount; edgeFrom++) {
        java.util.HashSet seenEdgeTo = new java.util.HashSet();
        java.util.Iterator iter = this.edgesFrom[edgeFrom].iterator();
        while (iter.hasNext()) {
            java.lang.Integer edgeTo = ((java.lang.Integer) (iter.next()));
            if (!seenEdgeTo.contains(edgeTo)) {
                newEdges.add(new robert.sheridan.algorithm.Edge(edgeFrom, edgeTo.intValue()));
                seenEdgeTo.add(edgeTo);
            }
        } 
    }
    robert.sheridan.algorithm.Edge newEdge[] = new robert.sheridan.algorithm.Edge[newEdges.size()];
    newEdges.<robert.sheridan.algorithm.Edge>toArray(newEdge);
    return new robert.sheridan.algorithm.Graph(this.nodecount, newEdge);
}

public static boolean orderedSetComparison(int[] set1, int[] set2) {
    if (set2 == null) {
        return false;
    }
    if (set1 == null) {
        return true;
    }
    final int smallerSize = java.lang.Math.min(set1.length, set2.length);
    int x;
    for (x = 0; x < smallerSize; x++) {
        if (set1[x] < set2[x]) {
            return true;
        }
    }
    return set1.length < set2.length;
}

