public robert.sheridan.algorithm.Graph getReducedGraph(int[] topologicalOrder) {
    if (topologicalOrder.length != this.nodecount) {
        throw new java.lang.IllegalArgumentException("topological ordering of nodes does not match nodecount");
    }
    if (!this.acyclic) {
        throw new java.lang.RuntimeException("attempt to compute transitive reduction on a graph with cycles");
    }
    int priorityIndex[] = new int[this.nodecount];
    int x;
    for (x = 0; x < topologicalOrder.length; x++) {
        priorityIndex[topologicalOrder[x]] = x;
    }
    java.util.LinkedList newEdges = new java.util.LinkedList();
    java.util.LinkedHashSet descendants[] = new java.util.LinkedHashSet[this.nodecount];
    int nodeIndex;
    for (nodeIndex = topologicalOrder.length - 1; nodeIndex >= 0; nodeIndex--) {
        int nodeId = topologicalOrder[nodeIndex];
        /* determine topologically ordered list of children */
        java.util.LinkedHashSet daughters = new java.util.LinkedHashSet(this.edgesFrom[nodeId]);
        robert.sheridan.algorithm.IntSortNode daughter[] = new robert.sheridan.algorithm.IntSortNode[daughters.size()];
        int daughterIndex = 0;
        java.util.Iterator iter = daughters.iterator();
        while (iter.hasNext()) {
            int daughterId = ((java.lang.Integer) (iter.next())).intValue();
            daughter[daughterIndex++] = new robert.sheridan.algorithm.IntSortNode(priorityIndex[daughterId], daughterId);
        } 
        java.util.Arrays.sort(daughter);
        for (daughterIndex = 0; daughterIndex < daughter.length; daughterIndex++) {
            int daughterId = daughter[daughterIndex].getSecond();
            java.lang.Integer daughterIdObj = new java.lang.Integer(daughterId);
            if (descendants[nodeId] == null) {
                if (descendants[daughterId] == null) {
                    descendants[nodeId] = new java.util.LinkedHashSet();
                } else {
                    descendants[nodeId] = new java.util.LinkedHashSet(descendants[daughterId]);
                }
                newEdges.add(new robert.sheridan.algorithm.Edge(nodeId, daughterId));
            } else {
                if (!descendants[nodeId].contains(daughterIdObj)) {
                    newEdges.add(new robert.sheridan.algorithm.Edge(nodeId, daughterId));
                } else {
                    /* child already descendant - transitive edge */
                }
                if (descendants[daughterId] != null) {
                    /* merge child descendants into descendants */
                    descendants[nodeId].addAll(descendants[daughterId]);
                }
            }
            descendants[nodeId].add(daughterIdObj);
        }
    }
    robert.sheridan.algorithm.Edge newEdge[] = new robert.sheridan.algorithm.Edge[newEdges.size()];
    newEdges.<java.lang.Object>toArray(newEdge);
    robert.sheridan.algorithm.Graph reducedGraph = new robert.sheridan.algorithm.Graph(this.nodecount, newEdge);
    reducedGraph.acyclic = true;
    reducedGraph.reduced = true;
    return reducedGraph;
}

