private int dependencyInjection(java.lang.String source, java.lang.String target, java.lang.String interfaze, tosin.oyetoyan.refsimulator.support.DecisionSupportTable2 dst2) {
    // if the edge is between a source and registry/mainclass skip
    if (target.equals(this.serviceLocator)) {
        return 0;
    }
    if (target.equals(this.mainClass)) {
        return 0;
    }
    // check to see whether the dependency still exist
    if (!this.map.get(source).contains(target)) {
        return 0;
    }
    this.helperRefactorInterface(target, interfaze, dst2);
    // update dstable2 bcos maps have changed
    this.setDSTable2Maps(dst2);
    dst2.updateTable(this.map);
    // we decide whether to use mFES only or utilize the abstraction for all dependencies
    if (this.isUseOnlyMFES()) {
        tosin.oyetoyan.refsimulator.support.Table2Schema s = dst2.getEdgeSchema(source, target);
        this.refactorExtractInterface(source, target, interfaze, s);
    } else {
        // check the remaining incoming dependencies (source inclusive) to target
        // interface utilization idea...
        melton.hayden.jepends.algorithm.ttcormenetal.CLR90Transpose<java.lang.String> transposer = new melton.hayden.jepends.algorithm.ttcormenetal.CLR90Transpose<java.lang.String>(this.map);
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> mapT = transposer.getMap();
        for (java.lang.String source1 : mapT.get(target)) {
            tosin.oyetoyan.refsimulator.support.Table2Schema s = dst2.getEdgeSchema(source, target);
            // replace the target's implementation with its abstraction (Interface) wherever possible
            if (s.getDecision().equals(tosin.oyetoyan.refsimulator.support.Strategy.EI)) {
                this.refactorExtractInterface(source1, target, interfaze, s);
            }
        }
    }
    return 0;
}

