            }
            if (sortPriority.equals(tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.FANIN)) {
                i = java.lang.Integer.compare(o2.getSccSize(), o1.getSccSize());// descending order

                k = java.lang.Integer.compare(o2.getFanin(), o1.getFanin());
                // j = String.valueOf(o2.isZtatic()).compareTo(String.valueOf(o1.isZtatic()));
                j = java.lang.Integer.compare(o2.getCrss(), o1.getCrss());
            }
            if (sortPriority.equals(tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.FANOUT)) {
                j = java.lang.Integer.compare(o1.getFanout(), o2.getFanout());// ascending order

                k = java.lang.Integer.compare(o2.getFanin(), o1.getFanin());// descending order

                // j = String.valueOf(o2.isZtatic()).compareTo(String.valueOf(o1.isZtatic()));
                i = java.lang.Integer.compare(o2.getSccSize(), o1.getSccSize());
                // i = Integer.compare(o2.getCrss(), o1.getCrss());
            }
            if (sortPriority.equals(tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.CRSS)) {
                k = java.lang.Integer.compare(o2.getCrss(), o1.getCrss());// descending order

                j = java.lang.Integer.compare(o2.getFanin(), o1.getFanin());
                i = java.lang.Integer.compare(o2.getSccSize(), o1.getSccSize());// descending order

                // i = String.valueOf(o2.isZtatic()).compareTo(String.valueOf(o1.isZtatic()));
            }
            if (sortPriority.equals(tosin.oyetoyan.refsimulator.support.ExtractInterfaceSupportTable1.STATIC)) {
                i = java.lang.Integer.compare(o2.getCrss(), o1.getCrss());// descending order

                j = java.lang.Integer.compare(o2.getFanin(), o1.getFanin());
                // i = Integer.compare(o2.getSccSize(), o1.getSccSize());	//descending order
                k = java.lang.String.valueOf(o2.isZtatic()).compareTo(java.lang.String.valueOf(o1.isZtatic()));
            }
            int retStatus = 0;
            if (k < 0) {
                retStatus = -1;
            } else if (k > 0) {
                retStatus = 1;
            } else if (j < 0) {
                retStatus = -1;
            } else if (j > 0) {
                retStatus = 1;
            } else if (i < 0) {
                retStatus = -1;
            } else if (i > 0) {
                retStatus = 1;
            }
            return retStatus;
        }
    });
}

