private void checkEquality(K k, java.util.Map<K, java.util.Set<K>> reachableMap) {
    java.util.Collection<K> keys = new java.util.LinkedList<K>(reachableMap.keySet());
    keys.remove(k);
    java.util.Set<K> s = reachableMap.get(k);
    for (K k2 : keys) {
        java.util.Set<K> original = reachableMap.get(k2);
        if (original.equals(s)) {
            reachableMap.put(k, original);
            return;
        }
    }
}

