public void processDecision() {
    this.decision = tosin.oyetoyan.refsimulator.support.Strategy.NONE;
    // if the target is an abstraction, set the decision to NONE
    if (this.isAbstract) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.NONE);
    }
    if (this.isInterface) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.NONE);
    }
    tosin.oyetoyan.refsimulator.support.ClassUsesTypes uses = this.usageTypes;
    // decision_set = new HashSet<String>();
    if (uses.isFieldDeclaration()) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.EI);
    }
    if (uses.isStaticFieldInvoke()) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.EF);
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.EI);
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.SR);
    }
    // check to find whether target has existing interface, if yes move_field to interface
    if (uses.isStaticFinalFieldInvoke()) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.CF);
        /* boolean ifaceExist = ClassUsesMaps.getInterfaceTypesMap().get(target).size() > 0;
        if(ifaceExist){
        decision_set.add(Strategy.MF);
        }else{

        }
         */
    }
    if (uses.isMethodParameter()) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.EI);
    }
    if (uses.isMethodReturn()) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.EI);
    }
    if (uses.isMethodException()) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.EA);
    }
    if (uses.isOtherType()) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.EI);
    }
    if (uses.isConstructorInvoke()) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.PR);
    }
    if (uses.isSuperType()) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.NONE);
    }
    if (uses.isInterfaceType()) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.NONE);
    }
    if (uses.isStaticMethod()) {
        if (this.isStatic) {
            if (this.dependsFanin > 1) {
                this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.EI);
                this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.SR);
            } else {
                this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.IM);
            }
        } else if (this.dependsFanin > 1) {
            this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.EI);
            this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.PR);
        } else {
            this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.IM);
        }
    }
    if (this.decision_set.contains(tosin.oyetoyan.refsimulator.support.Strategy.NONE)) {
        this.decision_set.clear();
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.NONE);
    }
    if (this.decision_set.isEmpty()) {
        this.decision_set.add(tosin.oyetoyan.refsimulator.support.Strategy.NONE);
    }
    // 
    if (this.decision_set.size() == 1) {
        this.decision = this.decision_set.iterator().next();
    } else if (this.decision_set.contains(tosin.oyetoyan.refsimulator.support.Strategy.PR)) {
        // compute decision in this order
        this.decision = tosin.oyetoyan.refsimulator.support.Strategy.PR;
    } else if (this.decision_set.contains(tosin.oyetoyan.refsimulator.support.Strategy.SR)) {
        this.decision = tosin.oyetoyan.refsimulator.support.Strategy.SR;
    } else if (this.decision_set.contains(tosin.oyetoyan.refsimulator.support.Strategy.EI)) {
        this.decision = tosin.oyetoyan.refsimulator.support.Strategy.EI;
    } else if (this.decision_set.contains(tosin.oyetoyan.refsimulator.support.Strategy.IM)) {
        this.decision = tosin.oyetoyan.refsimulator.support.Strategy.IM;
    } else if (this.decision_set.contains(tosin.oyetoyan.refsimulator.support.Strategy.CF)) {
        this.decision = tosin.oyetoyan.refsimulator.support.Strategy.CF;
    }
    // System.out.println(decision);
    /* decisionSetToString = new StringBuffer();	
    {
    String join = "";
    for(String d : decision_set){
    decisionSetToString.append(d);
    }
    }
     */
}

