private void updateSourceToInterfaceDependencies(java.lang.String source, java.lang.String target, java.lang.String itarget, tosin.oyetoyan.refsimulator.support.ClassUsesTypes cut) {
    if (cut.isStaticMethod()) {
        this.smMap.get(source).remove(target);
    }
    if (cut.isStaticFieldInvoke()) {
        this.sfMap.get(source).remove(target);
    }
    if (cut.isStaticFinalFieldInvoke()) {
        java.util.Set<java.lang.String> sffmap = this.sffMap.get(source);
        sffmap.remove(target);
        sffmap.add(itarget);
        this.updatePublisheMap(source, target, itarget);
    }
    if (cut.isFieldDeclaration()) {
        java.util.Set<java.lang.String> fmap = this.fMap.get(source);
        fmap.add(itarget);
        fmap.remove(target);
    }
    if (cut.isOtherType()) {
        java.util.Set<java.lang.String> omap = this.otherMap.get(source);
        omap.add(itarget);
        omap.remove(target);
    }
    if (cut.isConstructorInvoke()) {
        this.ciMap.get(source).remove(target);
    }
    if (cut.isMethodParameter()) {
        java.util.Set<java.lang.String> mpmap = this.mpMap.get(source);
        mpmap.add(itarget);
        mpmap.remove(target);
        this.updatePublisheMap(source, target, itarget);
    }
    if (cut.isMethodReturn()) {
        java.util.Set<java.lang.String> mrmap = this.mrMap.get(source);
        mrmap.add(itarget);
        mrmap.remove(target);
        this.updatePublisheMap(source, target, itarget);
    }
    if (cut.isMethodException()) {
        java.util.Set<java.lang.String> memap = this.meMap.get(source);
        memap.add(itarget);
        memap.remove(target);
        this.updatePublisheMap(source, target, itarget);
    }
}

