private boolean isSuperTypeOf(java.lang.String from, java.lang.String to, java.util.Map<java.lang.String, java.util.Set<java.lang.String>> supersMap) {
    // remove edge from `from' to `to'
    // implies that from is a supertype of to
    // so have to go supersMap.get(to).contains(from);
    // but need to do it transitively, ie mite not be direct supertype... grr
    java.util.Set<java.lang.String> supers = supersMap.get(to);
    if (supers.contains(from)) {
        return true;
    }
    for (java.lang.String s : supers) {
        boolean b = this.isSuperTypeOf(from, s, supersMap);
        if (b) {
            return true;
        }
    }
    return false;
}

