private void process(org.apache.bcel.classfile.JavaClass jc) {
    org.apache.bcel.classfile.Method[] ms = jc.getMethods();
    for (org.apache.bcel.classfile.Method method : ms) {
        org.apache.bcel.classfile.Code code = method.getCode();
        org.apache.bcel.generic.ConstantPoolGen cpg = new org.apache.bcel.generic.ConstantPoolGen(jc.getConstantPool());
        org.apache.bcel.generic.MethodGen mg = new org.apache.bcel.generic.MethodGen(method, "SomeClass", cpg);
        org.apache.bcel.generic.InstructionList il = mg.getInstructionList();
        if (il == null) {
            continue;
        }
        org.apache.bcel.generic.InstructionHandle[] ihs = il.getInstructionHandles();
        for (org.apache.bcel.generic.InstructionHandle handle : ihs) {
            org.apache.bcel.generic.Instruction instr = handle.getInstruction();
            java.lang.Class instrClass = instr.getClass();
            if (instr instanceof org.apache.bcel.generic.InvokeInstruction) {
                org.apache.bcel.generic.InvokeInstruction canonical = ((org.apache.bcel.generic.InvokeInstruction) (instr));
                java.lang.String s = canonical.getSignature(cpg);
                java.lang.String n = canonical.getMethodName(cpg);
                java.lang.String c = canonical.getClassName(cpg);
                // need to determine which classes have new called on them...
                // the appropriate method is named <init> (and has whatever args).
                this.usesInSizeMethCall.add(c);
                // add the method name where the dependency is found
                java.lang.String meth = method.getName();
                if (meth.equals("<init>")) {
                    meth = jc.getClassName().substring(jc.getClassName().lastIndexOf(".") + 1, jc.getClassName().length());
                }
                if (this.typesLocation.containsKey(c)) {
                    this.typesLocation.get(c).add(meth + "()");
                } else {
                    java.util.Set<java.lang.String> loc = new java.util.HashSet<java.lang.String>();
                    loc.add(meth + "()");
                    this.typesLocation.put(c, loc);
                }
                if (n.equals("<init>")) {
                    this.usesInSizeConstuctorCall.add(c);
                }
                if (instr instanceof org.apache.bcel.generic.INVOKESTATIC) {
                    this.usesInSizeMethCallStatic.add(c);
                    // usesInSizeMethCall.remove(c);
                }
            } else if (instr instanceof org.apache.bcel.generic.FieldInstruction) {
                org.apache.bcel.generic.FieldInstruction canon = ((org.apache.bcel.generic.FieldInstruction) (instr));
                java.lang.String c = canon.getClassName(cpg);
                java.lang.String f = canon.getFieldName(cpg);
                java.lang.String t = canon.getFieldType(cpg).toString();
                this.usesInSizeField.add(c);
                // add the method name where the dependency is found
                java.lang.String meth = method.getName();
                if (meth.equals("<init>")) {
                    meth = jc.getClassName().substring(jc.getClassName().lastIndexOf(".") + 1, jc.getClassName().length());
                }
                if (this.typesLocation.containsKey(c)) {
                    this.typesLocation.get(c).add(meth + "()");
                } else {
                    java.util.Set<java.lang.String> loc = new java.util.HashSet<java.lang.String>();
                    loc.add(meth + "()");
                    this.typesLocation.put(c, loc);
                }
                if ((instr instanceof org.apache.bcel.generic.GETSTATIC) || (instr instanceof org.apache.bcel.generic.PUTSTATIC)) {
                    this.usesInSizeFieldStatic.add(c);
                    if (this.usesInSizeFieldStaticType.containsKey(c)) {
                        this.usesInSizeFieldStaticType.get(c).add(f);
                    } else {
                        java.util.Set<java.lang.String> finalField = new java.util.HashSet<java.lang.String>();
                        finalField.add(f);
                        this.usesInSizeFieldStaticType.put(c, finalField);
                    }
                }
            }
        }
    }
}

