public FeedbackSetHeuristic(java.util.Map<java.lang.String, java.util.Set<java.lang.String>> allMap, java.util.Map<java.lang.String, java.util.Set<java.lang.String>> supersMap) {
    super();
    this.allMap = allMap;
    this.supersMap = supersMap;
    this.supersReachableMap = new melton.hayden.jepends.algorithm.ReachabilityMapGenerator<java.lang.String>(supersMap).getMap();
    this.map = new java.util.HashMap<java.lang.String, java.util.Set<java.lang.String>>();
    // only use the edges that we are allowed to get rid of
    for (java.lang.String key : allMap.keySet()) {
        java.util.Set<java.lang.String> set = allMap.get(key);
        java.util.Set<java.lang.String> copy = new java.util.HashSet<java.lang.String>(set);
        java.util.Set<java.lang.String> exclude = supersMap.get(key);
        // Set<String> exclude = new HashSet<String>();
        copy.removeAll(exclude);
        this.map.put(key, copy);
    }
    // initialise this puppy
    this.indegreeMap = new java.util.HashMap<java.lang.String, java.lang.Integer>();
    for (java.lang.String key : this.map.keySet()) {
        this.indegreeMap.put(key, 0);
    }
    this.outdegreeMap = new java.util.HashMap<java.lang.String, java.lang.Integer>();
    for (java.lang.String key : this.map.keySet()) {
        java.util.Set<java.lang.String> set = this.map.get(key);
        this.outdegreeMap.put(key, set.size());
        for (java.lang.String k : set) {
            int count = this.indegreeMap.get(k);
            this.indegreeMap.put(k, count + 1);
        }
    }
}

