public java.util.List<java.lang.Integer> pathFromAToB(int a, int b) {
    this.pathsAToB = new java.util.ArrayList<java.lang.Integer>();
    // The path will always end at b.
    this.pathsAToB.add(b);
    // Loop through each previous vertex until you get back to start.
    try {
        while (this.path[a][b] != a) {
            this.pathsAToB.add(this.path[a][b]);
            b = this.path[a][b];
        } 
        // Add start to the beginning of path
        this.pathsAToB.add(a);
    } catch (java.lang.Exception e) {
        this.pathsAToB = new java.util.ArrayList<java.lang.Integer>();
    }
    return this.pathsAToB;
}

