    java.util.LinkedList<robert.sheridan.algorithm.Edge> edges = new java.util.LinkedList();
    this.edgesFrom = new java.util.LinkedList[this.nodecount];
    this.edgesTo = new java.util.LinkedList[this.nodecount];
    int x;
    for (x = 0; x < this.nodecount; x++) {
        this.edgesFrom[x] = new java.util.LinkedList();
        this.edgesTo[x] = new java.util.LinkedList();
    }
    for (linebuf = br.readLine(); !linebuf.equals("."); linebuf = br.readLine()) {
        java.lang.String vertex[] = linebuf.trim().split("\\s+");
        if (vertex.length != 2) {
            throw new java.lang.NumberFormatException((("Illegal input to Graph constructor:\n" + "Expected two integers, received: ") + linebuf) + "\n");
        }
        int edgeFrom = java.lang.Integer.parseInt(vertex[0]);
        int edgeTo = java.lang.Integer.parseInt(vertex[1]);
        edges.add(new robert.sheridan.algorithm.Edge(edgeFrom, edgeTo));
        this.edgesFrom[edgeFrom].add(new java.lang.Integer(edgeTo));
        this.edgesTo[edgeTo].add(new java.lang.Integer(edgeFrom));
    }
    this.edge = new robert.sheridan.algorithm.Edge[edges.size()];
    edges.<robert.sheridan.algorithm.Edge>toArray(this.edge);
    this.acyclic = false;
    this.reduced = false;
}

