public int[] getCycleEliminationVertexPriority() {
    int priority[] = new int[this.nodecount];
    int inDegree[] = new int[this.nodecount];
    int outDegree[] = new int[this.nodecount];
    if (this.nodecount == 0) {
        return priority;
    }
    if (this.nodecount == 1) {
        priority[0] = 0;
        return priority;
    }
    robert.sheridan.algorithm.Graph simplifiedGraph = this.getGraphWithoutMultipleEdges().getGraphWithoutOneOrTwoCycles();
    if (this.nodecount == 2) {
        if (simplifiedGraph.edgesFrom[0].size() == 0) {
            /* node 0 is a sink */
            priority[0] = 1;
            priority[1] = 0;
        } else {
            priority[0] = 0;
            priority[1] = 1;
        }
        return priority;
    }
    java.util.LinkedList simpleEdgesTo[] = simplifiedGraph.edgesTo;
    java.util.LinkedList simpleEdgesFrom[] = simplifiedGraph.edgesFrom;
    java.util.LinkedList bucket[] = new java.util.LinkedList[(2 * this.nodecount) - 3];
    java.util.LinkedList Sr = new java.util.LinkedList();
    java.util.LinkedList Sl = new java.util.LinkedList();
    final int bucketOffset = this.nodecount - 2;
    int x;
    for (x = 0; x < bucket.length; x++) {
        bucket[x] = new java.util.LinkedList();
    }
    java.util.LinkedList sink = bucket[0];
    java.util.LinkedList source = bucket[bucket.length - 1];
    for (x = 0; x < this.nodecount; x++) {
        inDegree[x] = simpleEdgesTo[x].size();
        outDegree[x] = simpleEdgesFrom[x].size();
        if (outDegree[x] == 0) {
            sink.add(new java.lang.Integer(x));
        } else if (inDegree[x] == 0) {
            source.add(new java.lang.Integer(x));
        } else {
            bucket[(outDegree[x] - inDegree[x]) + bucketOffset].add(new java.lang.Integer(x));
        }
    }
    int scanBucketStart = bucket.length - 2;
    int nodesRemaining;
    for (nodesRemaining = this.nodecount; nodesRemaining != 0; nodesRemaining--) {
        /* select node */
        java.lang.Integer u;
        boolean goRight = false;
        if (sink.size() > 0) {
            u = ((java.lang.Integer) (sink.removeFirst()));
            goRight = true;
        } else if (source.size() > 0) {
            u = ((java.lang.Integer) (source.removeFirst()));
        } else {
            while (bucket[scanBucketStart].size() == 0) {
                scanBucketStart--;
            } 
            u = ((java.lang.Integer) (bucket[scanBucketStart].removeFirst()));
        }
        /* cut edges and adjust adjacent nodes */
        java.util.LinkedList simpleAdjacents = simpleEdgesTo[u.intValue()];
        while (simpleAdjacents.size() > 0) {
            java.lang.Integer adj = ((java.lang.Integer) (simpleAdjacents.removeFirst()));
            int adjindex = adj.intValue();
            int inDeg = inDegree[adjindex];
            int outDeg = outDegree[adjindex];
            if (outDeg == 0) {
                sink.remove(adj);
            } else if (inDeg == 0) {
                source.remove(adj);
            } else {
                bucket[(outDeg - inDeg) + bucketOffset].remove(adj);
            }
            simpleEdgesFrom[adjindex].remove(u);
            outDegree[adjindex]--;
            outDeg--;
            if (outDeg == 0) {
                sink.add(adj);
            } else if (inDeg == 0) {
                source.add(adj);
            } else {
                int dest = (outDeg - inDeg) + bucketOffset;
                bucket[dest].add(adj);
                if (dest > scanBucketStart) {
                    scanBucketStart = dest;
                }
            }
        } 
        simpleAdjacents = simpleEdgesFrom[u.intValue()];
        while (simpleAdjacents.size() > 0) {
            java.lang.Integer adj = ((java.lang.Integer) (simpleAdjacents.removeFirst()));
            int adjindex = adj.intValue();
            int inDeg = inDegree[adjindex];
            int outDeg = outDegree[adjindex];
            if (outDeg == 0) {
                sink.remove(adj);
            } else if (inDeg == 0) {
                source.remove(adj);
            } else {
                bucket[(outDeg - inDeg) + bucketOffset].remove(adj);
            }
            simpleEdgesTo[adjindex].remove(u);
            inDegree[adjindex]--;
            inDeg--;
            if (outDeg == 0) {
                sink.add(adj);
            } else if (inDeg == 0) {
                source.add(adj);
            } else {
                int dest = (outDeg - inDeg) + bucketOffset;
                bucket[dest].add(adj);
                if (dest > scanBucketStart) {
                    scanBucketStart = dest;
                }
            }
        } 
        /* add to appropriate list */
        if (goRight) {
            Sr.addFirst(u);
        } else {
            Sl.addLast(u);
        }
    }
    x = 0;
    java.util.Iterator iter = Sl.iterator();
    while (iter.hasNext()) {
        priority[x++] = ((java.lang.Integer) (iter.next())).intValue();
    } 
    iter = Sr.iterator();
    while (iter.hasNext()) {
        priority[x++] = ((java.lang.Integer) (iter.next())).intValue();
    } 
    return priority;
}

