private void fitnessSCC(boolean pre) {
    melton.hayden.jepends.analysis.Analyser analyse = new melton.hayden.jepends.analysis.Analyser();
    analyse.analyse(this.map);
    int minscc = java.lang.Integer.MAX_VALUE;
    int maxscc = 0;
    org.apache.commons.math3.stat.descriptive.SummaryStatistics sm = new org.apache.commons.math3.stat.descriptive.SummaryStatistics();
    for (java.util.Set<java.lang.String> scc : analyse.getSccs()) {
        minscc = java.lang.Math.min(minscc, scc.size());
        maxscc = java.lang.Math.max(maxscc, scc.size());
        sm.addValue(scc.size());// can use this instead of Math lib

    }
    // set fitness
    if (pre) {
        this.fitness.setPreRefactoring_MinSCCSize(minscc);
        this.fitness.setPreRefactoring_MaxSCCSize(maxscc);
        this.fitness.setPreRefactoringNumOfSCCs(analyse.getSccs().size());
        this.fitness.setPreRefactoring_MeanSCC(sm.getMean());
    } else {
        // post
        this.fitness.setPostRefactoring_MinSCCSize(minscc);
        this.fitness.setPostRefactoring_MaxSCCSize(maxscc);
        this.fitness.setPostRefactoringNumOfSCCs(analyse.getSccs().size());
        this.fitness.setPostRefactoring_MeanSCC(sm.getMean());
    }
}

