    java.util.List<java.lang.String> scc_l = new java.util.ArrayList<java.lang.String>(scc);
    java.util.Collection<java.util.Set<java.lang.String>> parents = supersMap.values();
    java.util.Set<java.lang.String> allParents = new java.util.HashSet<java.lang.String>();
    for (java.util.Set<java.lang.String> set : parents) {
        allParents.addAll(set);
    }
    // find the parents in scc
    allParents.retainAll(scc);
    // System.out.println(allParents);
    for (java.lang.String k : allParents) {
        java.util.Set<java.lang.String> stk = map.get(k);
        java.util.Set<java.lang.String> par_to_par = supersMap.get(k);
        stk.removeAll(par_to_par);// if we have super extends super; remove them from the list:need only uses relation

        stk.retainAll(scc);// we need only those formed in the current cycle

        // System.out.println(stk);
        for (java.lang.String stk1 : stk) {
            stks.add(new robert.sheridan.algorithm.Edge(scc_l.indexOf(k), scc_l.indexOf(stk1)));
        }
    }
    return stks;
}

