private void collectEdgeFromGraph() {
    java.util.List<robert.sheridan.algorithm.Edge> edge = new java.util.ArrayList<robert.sheridan.algorithm.Edge>();
    for (int i = 0; i < this.graph.length; i++) {
        for (int j = 0; j < this.graph.length; j++) {
            if (this.graph[i][j] == 1) {
                edge.add(new robert.sheridan.algorithm.Edge(i, j));
            }
        }
    }
    // reconstruct
    this.a_edge = new robert.sheridan.algorithm.Edge[edge.size()];
    int index = 0;
    for (robert.sheridan.algorithm.Edge e : edge) {
        this.a_edge[index++] = e;
    }
}

