public void run(boolean notJar) throws java.lang.Throwable {
    java.util.List<melton.hayden.jepends.bytecode.ClassDependencyInferrer> depInfs = new java.util.LinkedList<melton.hayden.jepends.bytecode.ClassDependencyInferrer>();
    tosin.oyetoyan.refsimulator.bytecode.ClassReader cr = new tosin.oyetoyan.refsimulator.bytecode.ClassReader();
    cr.readDir(this.inDir);
    for (java.lang.String name : cr.getClasses()) {
        try {
            java.io.InputStream in = new java.io.FileInputStream(name);
            org.apache.bcel.classfile.ClassParser parser = new org.apache.bcel.classfile.ClassParser(in, "");
            org.apache.bcel.classfile.JavaClass clazz = parser.parse();
            in.close();
            java.lang.String clazzName = clazz.getClassName();
            // System.out.println(clazzName);
            if (this.acceptClass(clazzName)) {
                melton.hayden.jepends.bytecode.ClassDependencyInferrer depInf = new melton.hayden.jepends.bytecode.ClassDependencyInferrer(clazz, this.prefixes);
                depInfs.add(depInf);
            }
        } catch (java.lang.Throwable t) {
            java.lang.System.err.println("Some problem with " + name);
            t.printStackTrace();
        }
    }
    // process for staticFinalFields Dependencies
    this.helperDependencyForStaticFinalFields(depInfs);
    java.util.Collections.<melton.hayden.jepends.bytecode.ClassDependencyInferrer>sort(depInfs, new java.util.Comparator<melton.hayden.jepends.bytecode.ClassDependencyInferrer>() {
        2() {
            super();
        }

        public int compare(melton.hayden.jepends.bytecode.ClassDependencyInferrer left, melton.hayden.jepends.bytecode.ClassDependencyInferrer right) {
            return left.getClassName().compareTo(right.getClassName());
        }
    });
    melton.hayden.jepends.bytecode.DependencyFileWriter writer = new melton.hayden.jepends.bytecode.DependencyFileWriter(this.outDir, depInfs);
    writer.writeAll();
    // jb.setValue(ClassCounter++);
}

