public static java.util.Map<java.lang.String, java.util.Set<java.lang.String>> ExtractPackage(java.util.Map<java.lang.String, java.util.Set<java.lang.String>> table) {
    java.util.Map<java.lang.String, java.util.Set<java.lang.String>> duptable = new java.util.HashMap<java.lang.String, java.util.Set<java.lang.String>>();
    for (java.lang.String key : table.keySet()) {
        java.util.Set<java.lang.String> fanout = new java.util.HashSet<java.lang.String>();
        java.lang.String keyp = tosin.oyetoyan.refsimulator.utility.PackageUtil.getPackage(key);
        for (java.lang.String f : table.get(key)) {
            fanout.add(tosin.oyetoyan.refsimulator.utility.PackageUtil.getPackage(f));
        }
        fanout.remove(keyp);
        // add package and package fanouts to map
        if (duptable.containsKey(keyp)) {
            duptable.get(keyp).addAll(fanout);
        } else {
            duptable.put(keyp, fanout);
        }
    }
    return duptable;
}

public void analyse() {
    java.lang.String[] toMerge = new java.lang.String[]{ "_all.txt", "_allInSizeInclSupers.txt", "_allInTheInterfaceInclSupers.txt" };
    java.lang.System.out.println("analyse");
    // CRSS stuff
    for (java.lang.String f : toMerge) {
        java.io.File inFile = new java.io.File(this.inDir, f);
        java.lang.System.out.println("    " + inFile);
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> map = melton.hayden.jepends.analysis.MapFileParser.parse(inFile);
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> eqByRefMap = new melton.hayden.jepends.analysis.EqualityByReferenceMapGenerator<java.lang.String>(map).getMap();
        map = null;
        java.util.Map<java.lang.String, java.util.List<java.lang.String>> outMap = new java.util.LinkedHashMap<java.lang.String, java.util.List<java.lang.String>>();
        outMap.put("class", new java.util.LinkedList<java.lang.String>());
        for (java.lang.String key : eqByRefMap.keySet()) {
            outMap.put(key, new java.util.LinkedList<java.lang.String>());
        }
        this.crss(eqByRefMap, outMap);
        this.scc(eqByRefMap, outMap);
        melton.hayden.jepends.analysis.MapFileWriter writer = new melton.hayden.jepends.analysis.MapFileWriter(outMap, new java.io.File(this.outDir, f));
        writer.write();
    }
}

