    for (java.lang.String key : all.keySet()) {
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> allMap = new melton.hayden.jepends.analysis.EqualityByReferenceMapGenerator<java.lang.String>(melton.hayden.jepends.analysis.MapFileParser.parse(all.get(key))).getMap();
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> superMap = new melton.hayden.jepends.analysis.EqualityByReferenceMapGenerator<java.lang.String>(melton.hayden.jepends.analysis.MapFileParser.parse(supers.get(key))).getMap();
        melton.hayden.jepends.algorithm.ttcormenetal.CLR90SCC<java.lang.String> sccGenerator = new melton.hayden.jepends.algorithm.ttcormenetal.CLR90SCC<java.lang.String>(allMap);
        sccGenerator.run();
        long before = java.lang.System.currentTimeMillis();
        for (int i = 0; i < 100; i++) {
            java.util.List<java.util.Set<java.lang.String>> sccs = sccGenerator.getSCCs();
            for (java.util.Set<java.lang.String> set : sccs) {
                if (set.size() == 1) {
                    continue;
                }
                java.util.Map<java.lang.String, java.util.Set<java.lang.String>> culledAllMap = this.cullMap(allMap, set);
                java.util.Map<java.lang.String, java.util.Set<java.lang.String>> culledSuperMap = this.cullMap(superMap, set);
                melton.hayden.jepends.analysis.FeedbackSetHeuristic feedbackSetHeuristic = new melton.hayden.jepends.analysis.FeedbackSetHeuristic(culledAllMap, culledSuperMap);
                feedbackSetHeuristic.run(new java.util.Random(0), true);
            }
        }
        long after = java.lang.System.currentTimeMillis();
        long diff = after - before;
        java.lang.System.out.println((((key + "\t") + allMap.size()) + "\t") + diff);
    }
    java.lang.System.out.println();
}

