public robert.sheridan.algorithm.Graph[] partition(int[] partitionIndex, int[] nodeRenumber) {
    if ((partitionIndex.length != this.nodecount) || (nodeRenumber.length != this.nodecount)) {
        throw new java.lang.IllegalArgumentException("partitionGraph received wrong sized argument");
    }
    int partitionNodecount[] = new int[this.nodecount];
    int numberOfPartitions = 0;
    int x;
    for (x = 0; x < this.nodecount; x++) {
        nodeRenumber[x] = partitionNodecount[partitionIndex[x]]++;
        if (nodeRenumber[x] == 0) {
            numberOfPartitions++;
        }
    }
    java.util.LinkedList partitionEdges[] = new java.util.LinkedList[numberOfPartitions];
    for (x = 0; x < numberOfPartitions; x++) {
        partitionEdges[x] = new java.util.LinkedList();
    }
    for (x = 0; x < this.edge.length; x++) {
        robert.sheridan.algorithm.Edge e = this.edge[x];
        if (partitionIndex[e.getFrom()] != partitionIndex[e.getTo()]) {
            /* ignore edges which straddle partitions */
            continue;
        }
        partitionEdges[partitionIndex[e.getFrom()]].add(new robert.sheridan.algorithm.Edge(nodeRenumber[e.getFrom()], nodeRenumber[e.getTo()]));
    }
    robert.sheridan.algorithm.Graph retval[] = new robert.sheridan.algorithm.Graph[numberOfPartitions];
    for (x = 0; x < numberOfPartitions; x++) {
        robert.sheridan.algorithm.Edge pe[] = new robert.sheridan.algorithm.Edge[partitionEdges[x].size()];
        partitionEdges[x].<java.lang.Object>toArray(pe);
        retval[x] = new robert.sheridan.algorithm.Graph(partitionNodecount[x], pe);
    }
    return retval;
}

