public void run(java.util.List<K> keys) {
    if (this.timestamp != 0) {
        return;
    }
    for (K k : keys) {
        if (!this.visited.contains(k)) {
            this.trees.add(new java.util.HashSet<K>());
        }
        this.dfs(k);
    }
}

