private int[][] distance(int[][] adj, int[][] path, java.lang.String type) {
    int n = adj.length;
    int[][] ans = new int[n][n];
    // Implement algorithm on a copy matrix so that the adjacency isn't
    // destroyed.
    tosin.oyetoyan.refsimulator.utility.Copy2DArray.copy(ans, adj);
    // Compute successively better paths through vertex k.
    for (int k = 0; k < n; k++) {
        // Do so between each possible pair of points.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (type.equals(tosin.oyetoyan.refsimulator.graph.GraphDistance.SHORTEST)) {
                    if ((ans[i][k] == java.lang.Integer.MAX_VALUE) || (ans[k][j] == java.lang.Integer.MAX_VALUE)) {
                        continue;
                    }
                    if ((ans[i][k] + ans[k][j]) < ans[i][j]) {
                        ans[i][j] = ans[i][k] + ans[k][j];
                        path[i][j] = path[k][j];
                    }
                }
            }
        }
    }
    if (type.equals(tosin.oyetoyan.refsimulator.graph.GraphDistance.SHORTEST)) {
        // set cell with value of inf to -1 ...
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (ans[i][j] == java.lang.Integer.MAX_VALUE) {
                    ans[i][j] = -1;
                }
            }
        }
    }
    // Return the shortest path matrix.
    return ans;
}

