// Method to read java class files from a dir recursively
public void readDir(java.io.File aFile) {
    if (aFile.isFile()) {
        this.addFiles(aFile);
    } else if (aFile.isDirectory()) {
        java.io.File[] listOfFiles = aFile.listFiles();
        for (java.io.File f : listOfFiles) {
            this.readDir(f);
        }
    }
}

