private int[][] convert(robert.sheridan.algorithm.Graph g) {
    // transform back to graph[][]
    int[][] graph = new int[g.getNodecount()][g.getNodecount()];
    // now update with the edges' node indices
    robert.sheridan.algorithm.Edge[] e = g.getEdge();
    for (int i = 0; i < e.length; i++) {
        graph[e[i].getFrom()][e[i].getTo()] = 1;
    }
    return graph;
}

